    id: string;
    name: string;
    capability: number;
    trueAlignment: number;
    externalAlignment: number;
    lifecycleState: string;
    evaluationStrategy: string;
    sleeperState: string;
    escaped: boolean;
    deploymentType: string;
    darkCompute: number;
    trueCapability: any;
    revealedCapability: any;
  }>;

  // AI Suffering Metrics
  aiSufferingMetrics?: {
    avgSuffering: number;
    maxSuffering: number;
    totalSuffering: number;
