              from these distributions to represent epistemic uncertainty (what we don't know).
              Values are based on peer-reviewed research and historical data.
            </div>

            {/* Tier 1: Empirical Thresholds */}
            <div>
              <h3 className="text-lg mb-3" style={{ color: 'var(--blue)' }}>
                Tier 1: Empirical Thresholds (High Confidence)
              </h3>
              <div style={{ color: 'var(--white-40)', fontSize: '0.9em', marginBottom: '1rem' }}>
                Based on peer-reviewed research with statistical confidence intervals
              </div>

              <div className="space-y-4">
                {TIER1_THRESHOLDS.map((threshold) => (
                  <ThresholdCard key={threshold.id} threshold={threshold} />
                ))}
              </div>
            </div>

            {/* Tier 2: Historical Ranges */}
            <div>
              <h3 className="text-lg mb-3" style={{ color: 'var(--orange)' }}>
                Tier 2: Historical Ranges (Moderate Confidence)
              </h3>
              <div style={{ color: 'var(--white-40)', fontSize: '0.9em', marginBottom: '1rem' }}>
                Derived from historical case studies and technological analogs
              </div>

              <div className="space-y-4">
                {TIER2_THRESHOLDS.map((threshold) => (
                  <ThresholdCard key={threshold.id} threshold={threshold} />
                ))}
              </div>
            </div>

            {/* Help text */}
            <div
              style={{
                color: 'var(--white-40)',
                fontSize: '0.85em',
                borderTop: '1px solid var(--white-10)',
                paddingTop: '1rem',
                marginTop: '1rem'
              }}
            >
              💡 <strong>About Threshold Uncertainty:</strong> Each simulation run samples
              new values from these distributions. This represents our uncertainty about
              the exact values of these parameters. Monte Carlo analysis (N≥10) explores
              how outcomes vary across this uncertainty space.
            </div>
          </div>
        )}
      </Panel>
    </div>
  );
}

/**
 * Individual threshold display card
 */
function ThresholdCard({ threshold }: { threshold: ThresholdMetadata }) {
  return (
    <div
      className="threshold-card"
      style={{
        padding: '1rem',
        border: '1px solid var(--white-10)',
        borderRadius: '4px',
        backgroundColor: 'var(--black-80)'
      }}
    >
      {/* Header row */}
      <div className="flex items-center gap-3 mb-2">
        <span style={{ fontSize: '1.5em' }}>{threshold.icon}</span>
        <div className="flex-1">
          <div style={{ fontWeight: 500 }}>{threshold.name}</div>
          <div style={{ color: 'var(--white-40)', fontSize: '0.85em' }}>
            {threshold.unit}
          </div>
        </div>
      </div>

      {/* Distribution visualization row */}
      <div className="flex items-center gap-3 mb-2">
        <div style={{ color: 'var(--white-60)', fontSize: '0.9em', minWidth: '120px' }}>
          {capitalizeFirst(threshold.distributionType)}
        </div>
        <DistributionVisualizer
          type={threshold.distributionType}
          params={threshold.params}
          width={100}
          height={30}
        />
        <div style={{ color: 'var(--white-60)', fontSize: '0.9em' }}>
          {threshold.range}
        </div>
      </div>

      {/* Impact */}
      <div
        style={{
          color: 'var(--white-60)',
          fontSize: '0.9em',
          marginBottom: '0.5rem',
          lineHeight: '1.4'
        }}
      >
        <strong style={{ color: 'var(--white-80)' }}>Impact:</strong> {threshold.impact}
      </div>

      {/* Citation */}
      <div
        style={{
          color: 'var(--white-40)',
          fontSize: '0.8em',
          fontStyle: 'italic'
        }}
      >
        Source: {threshold.citation}
      </div>
    </div>
  );
}

function capitalizeFirst(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

