  const alignmentConfig = config.alignmentDynamics ?? DEFAULT_ALIGNMENT_DYNAMICS_CONFIG;

  const handleAlignmentUpdate = (updates: Partial<AlignmentDynamicsConfig>) => {
    dispatch({
      type: 'UPDATE_CONFIG',
      payload: {
        alignmentDynamics: {
          ...alignmentConfig,
          ...updates
        }
      }
    });
