/**
 * Threshold Config Modal Section
 *
 * Compact version of threshold configuration for the initialization modal.
 * Shows research-backed threshold distributions with editing capability.
 */

'use client';

import { useState } from 'react';

interface ThresholdInfo {
  id: string;
  name: string;
  icon: string;
  defaultMin: number;
  defaultMax: number;
  defaultMode?: number;
  type: 'Normal' | 'Beta' | 'Triangular' | 'Uniform';
  unit: string;
}

const THRESHOLDS: ThresholdInfo[] = [
  // Tier 1: Empirical
  { id: 'climateSensitivity', name: 'Climate Sensitivity', icon: '🌍', defaultMin: 2.0, defaultMax: 5.0, type: 'Normal', unit: '°C' },
  { id: 'socialCriticalMass', name: 'Social Critical Mass', icon: '👥', defaultMin: 0.20, defaultMax: 0.30, type: 'Normal', unit: '' },
  { id: 'trustRecoveryRate', name: 'Trust Recovery Rate', icon: '🛡️', defaultMin: 0.005, defaultMax: 0.03, type: 'Beta', unit: '/mo' },
  { id: 'automationSpeed', name: 'Automation Speed', icon: '🤖', defaultMin: 0.05, defaultMax: 0.30, type: 'Beta', unit: '/yr' },
  { id: 'detectionCeiling', name: 'Detection Ceiling', icon: '🔍', defaultMin: 0.15, defaultMax: 0.35, type: 'Beta', unit: '' },
  // Tier 2: Historical
  { id: 'govLegitimacyCrisis', name: 'Gov Legitimacy Crisis', icon: '🏛️', defaultMin: 0.25, defaultMode: 0.30, defaultMax: 0.40, type: 'Triangular', unit: '' },
  { id: 'surveillanceDystopia', name: 'Surveillance Dystopia', icon: '👁️', defaultMin: 0.65, defaultMax: 0.80, type: 'Uniform', unit: '' },
  { id: 'unemploymentCrisis', name: 'Unemployment Crisis', icon: '📉', defaultMin: 0.40, defaultMode: 0.50, defaultMax: 0.60, type: 'Triangular', unit: '' },
  { id: 'aiRecursiveImprovement', name: 'AI Recursive Improvement', icon: '🔄', defaultMin: 1.2, defaultMax: 1.5, type: 'Uniform', unit: '×/mo' },
  { id: 'resentmentRevolt', name: 'Resentment Revolt', icon: '😡', defaultMin: 0.60, defaultMode: 0.70, defaultMax: 0.80, type: 'Triangular', unit: '' },
];

export interface ThresholdOverrides {
  [key: string]: { min: number; max: number; mode?: number };
}

interface ThresholdConfigModalProps {
  overrides?: ThresholdOverrides;
  onChange?: (overrides: ThresholdOverrides | undefined) => void;
}

export function ThresholdConfigModal({ overrides, onChange }: ThresholdConfigModalProps) {
  const [expanded, setExpanded] = useState(false);
  const [customMode, setCustomMode] = useState(false);

  return (
    <div>
      <label className="block text-xs mb-2" style={{ color: 'var(--white-40)' }}>
        THRESHOLD UNCERTAINTY
        <button
          type="button"
          onClick={() => setExpanded(!expanded)}
          className="ml-2 text-cyan-400 hover:text-cyan-300"
        >
          [{expanded ? 'collapse' : 'view 10 thresholds'}]
        </button>
      </label>

      {!expanded ? (
        <div className="text-xs px-3 py-2 bg-black/50 border border-white/10 rounded" style={{ color: 'var(--white-60)' }}>
          Research-backed distributions sampling epistemic uncertainty for 10 critical parameters
        </div>
      ) : (
        <div className="space-y-2 max-h-64 overflow-y-auto px-3 py-2 bg-black/50 border border-white/10 rounded">
          {THRESHOLDS.map((threshold, idx) => (
            <div
              key={threshold.name}
              className="flex items-center justify-between text-xs py-1"
              style={{
                borderBottom: idx < THRESHOLDS.length - 1 ? '1px solid var(--white-5)' : 'none'
              }}
            >
              <div className="flex items-center gap-2 flex-1">
                <span className="text-sm">{threshold.icon}</span>
                <span style={{ color: 'var(--white-80)' }}>{threshold.name}</span>
              </div>
              <div className="flex items-center gap-2">
                <span style={{ color: 'var(--white-40)', fontSize: '0.7rem' }}>{threshold.type}</span>
                <span style={{ color: 'var(--cyan)' }}>{threshold.range}</span>
              </div>
            </div>
          ))}
          <div className="text-xs pt-2 mt-2 border-t" style={{ color: 'var(--white-40)', borderColor: 'var(--white-10)' }}>
            💡 Each run samples new values from these distributions. See docs for research citations.
          </div>
        </div>
      )}
    </div>
  );
}

