     1→/**
     2→ * IndexedDB wrapper for persistent event storage
     3→ *
     4→ * Stores all simulation events across runs for infinite scroll timeline.
     5→ * Events are indexed by simulation run and timestamp for efficient querying.
     6→ */
     7→
     8→interface StoredEvent {
     9→  id: string;                 // Unique event ID
    10→  simulationId: string;       // Simulation run ID (seed + scenario)
    11→  timestamp: number;          // Month when event occurred
    12→  type: string;
    13→  category: string;
    14→  description: string;
    15→  severity: 'low' | 'medium' | 'high' | 'critical';
    16→  insertedAt: number;         // Real-world timestamp when stored
    17→}
    18→
    19→const DB_NAME = 'simulation_events';
    20→const DB_VERSION = 1;
    21→const STORE_NAME = 'events';
    22→
    23→class EventDatabase {
    24→  private db: IDBDatabase | null = null;
    25→  private initPromise: Promise<void> | null = null;
    26→
    27→  /**
    28→   * Initialize IndexedDB connection
    29→   */
    30→  async init(): Promise<void> {
    31→    if (this.db) return; // Already initialized
    32→    if (this.initPromise) return this.initPromise; // Initialization in progress
    33→
    34→    this.initPromise = new Promise((resolve, reject) => {
    35→      if (typeof window === 'undefined' || !window.indexedDB) {
    36→        console.warn('[EventDB] IndexedDB not available (SSR or unsupported browser)');
    37→        resolve();
    38→        return;
    39→      }
    40→
    41→      const request = indexedDB.open(DB_NAME, DB_VERSION);
    42→
    43→      request.onerror = () => {
    44→        console.error('[EventDB] Failed to open database:', request.error);
    45→        reject(request.error);
    46→      };
    47→
    48→      request.onsuccess = () => {
    49→        this.db = request.result;
    50→        console.log('[EventDB] Database opened successfully');
    51→        resolve();
    52→      };
    53→
    54→      request.onupgradeneeded = (event) => {
    55→        const db = (event.target as IDBOpenDBRequest).result;
    56→
    57→        // Create object store if it doesn't exist
    58→        if (!db.objectStoreNames.contains(STORE_NAME)) {
    59→          const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
