import type { TippingPointSystem } from './tipping-points';

// Re-export all types for backward compatibility
export type {
  ScenarioMode,
  ScenarioParameters,
  ConfigurationSettings,
  RNGFunction
} from './config';

export type {
  GameEvent,
  GameAction,
  AgentType
} from './events';

export type {
  ExtinctionType,
