  const getEffectiveValue = (id: string, field: 'min' | 'max' | 'mode'): number => {
    const threshold = THRESHOLDS.find(t => t.id === id);
    if (!threshold) return 0;

    if (overrides?.[id]?.[field] !== undefined) {
      return overrides[id][field]!;
    }

    if (field === 'min') return threshold.defaultMin;
    if (field === 'max') return threshold.defaultMax;
    if (field === 'mode') return threshold.defaultMode || (threshold.defaultMin + threshold.defaultMax) / 2;
    return 0;
  };

  return (
    <div>
      <label className="block text-xs mb-2" style={{ color: 'var(--white-40)' }}>
        THRESHOLD UNCERTAINTY
        <button
          type="button"
