   426→function handleInit(seed: number, scenario?: ScenarioMode, interval?: number, alignmentConfig?: import('../types/alignment-dynamics').AlignmentDynamicsConfig, climatePriorityConfig?: import('../types/climate-priority').ClimatePriorityConfig, thresholdOverrides?: any) {
   427→  if (engine || state) {
   428→    throw new Error('Already initialized. Create a new worker to reinitialize.');
   429→  }
   430→
   431→  // Reset history buffer
   432→  metricHistory = {
   433→    westernLiberalIndex: [],
   434→    developmentIndex: [],
   435→    ecologicalIndex: [],
   436→    indigenousIndex: [],
   437→    qualityOfLife: [],
   438→    population: [],
   439→    climateChange: [],
   440→    biodiversityLoss: [],
   441→    socialCohesion: [],
   442→    institutionalTrust: [],
   443→    meaningLevel: [],
   444→    governmentComprehension: [],
   445→    internationalCooperation: [],
   446→    governmentAIRegulation: [],
   447→  };
   448→
   449→  // Create engine with seed (use 'summary' log level for minimal logging)
   450→  engine = new SimulationEngine({ seed, maxMonths: Infinity, logLevel: 'summary' });
   451→
   452→  // Create initial state with optional alignment, climate, and threshold configs
   453→  state = createDefaultInitialState(scenario || 'historical', alignmentConfig, climatePriorityConfig, thresholdOverrides);
   454→
   455→  // Set speed if provided
   456→  if (interval !== undefined) {
   457→    stepInterval = interval;
   458→  }
   459→
   460→  // Initialize calendar tracking (for UI display only)
   461→  startDate = new Date();
   462→  currentCalendarDate = new Date(startDate); // Clone startDate
   463→  currentDay = 1; // Simulation always starts at day 1
   464→  totalSimulationDaysElapsed = 0; // Reset simulation day counter
   465→
   466→  // Simulation state always starts at month 0, day 1 (not today's date)
   467→  // The actual calendar date is tracked separately for UI display only
   468→
   469→  // Create initial snapshot
   470→  const snapshot: InitialStateSnapshot = {
   471→    currentMonth: state.currentMonth,
   472→    currentYear: state.currentYear,
   473→    qualityOfLife: state.globalMetrics.qualityOfLife,
   474→    population: state.humanPopulationSystem.population,
   475→    aiCount: state.aiAgents.length,
   476→    scenario: scenario || 'historical'
   477→  };
   478→
   479→  // Store previous state for delta calculation
   480→  previousState = captureStateSnapshot(state);
   481→
   482→  self.postMessage({
   483→    type: 'initialized',
   484→    initialState: snapshot,
   485→    startDate: startDate.toISOString()
   486→  } as WorkerResponse);
   487→
   488→  // Immediately send full state delta so dashboard shows initial values
   489→  // This populates paradigms, environmental metrics, government, etc.
   490→  const initialDelta = calculateDelta(previousState, state, true); // Force full delta
   491→
   492→  // DEBUG: Log what's in the initial delta
   493→  console.log('[Worker] Initial delta contains:', {
   494→    population: initialDelta.population,
   495→    qualityOfLife: initialDelta.qualityOfLife,
   496→    westernLiberalIndex: initialDelta.westernLiberalIndex,
   497→    developmentIndex: initialDelta.developmentIndex
   498→  });
   499→
   500→  // Test which fields are serializable
   501→  try {
   502→    structuredClone(initialDelta);
   503→  } catch (cloneError) {
   504→    console.error('[Worker] Initial delta contains non-serializable data:', cloneError);
   505→    // Test each field individually to find the culprit
   506→    for (const [key, value] of Object.entries(initialDelta)) {
   507→      try {
   508→        structuredClone(value);
   509→      } catch (fieldError) {
   510→        console.error(`[Worker] Field "${key}" is not serializable:`, fieldError);
   511→      }
   512→    }
   513→  }
   514→
   515→  self.postMessage({
   516→    type: 'update',
   517→    delta: initialDelta,
   518→    month: state.currentMonth,
   519→    day: currentDay,
   520→    calendarDate: startDate.toISOString(),
   521→    timestamp: Date.now()
   522→  } as WorkerResponse);
   523→}
   524→
   525→function handleStart() {
   526→  if (!engine || !state) {
   527→    throw new Error('Not initialized. Call init() first.');
   528→  }
   529→
   530→  if (running) {
   531→    return; // Already running
   532→  }
   533→
   534→  running = true;
   535→  isFirstStep = true; // Force full delta on first step
   536→  startSimulationLoop();
   537→
   538→  // Notify UI that simulation is now running
   539→  self.postMessage({
   540→    type: 'resumed',
   541→    month: state.currentMonth,
   542→    day: currentDay
   543→  } as WorkerResponse);
   544→}
   545→
   546→function handlePause() {
   547→  if (!running) {
   548→    return; // Already paused
   549→  }
   550→
   551→  running = false;
   552→
   553→  // Stop both simulation and day intervals
   554→  if (simulationIntervalId !== null) {
   555→    clearInterval(simulationIntervalId);
   556→    simulationIntervalId = null;
   557→  }
   558→  if (dayIntervalId !== null) {
   559→    clearInterval(dayIntervalId);
   560→    dayIntervalId = null;
   561→  }
   562→
   563→  self.postMessage({
   564→    type: 'paused',
   565→    month: state?.currentMonth || 0,
   566→    day: currentDay
   567→  } as WorkerResponse);
   568→}
   569→
   570→function handleResume() {
   571→  if (!engine || !state) {
   572→    throw new Error('Not initialized');
   573→  }
   574→
   575→  if (running) {
   576→    return; // Already running
   577→  }
   578→
   579→  running = true;
   580→  startSimulationLoop();
   581→
   582→  self.postMessage({
   583→    type: 'resumed',
   584→    month: state.currentMonth,
   585→    day: currentDay
   586→  } as WorkerResponse);
   587→}
   588→
   589→function handleStep() {
   590→  if (!engine || !state || !startDate) {
   591→    throw new Error('Not initialized');
   592→  }
   593→
   594→  if (!currentCalendarDate) {
   595→    throw new Error('Calendar not initialized');
   596→  }
   597→
   598→  // Track previous month/year for month-crossing detection
   599→  const previousCalendarMonth = currentCalendarDate.getMonth();
   600→  const previousCalendarYear = currentCalendarDate.getFullYear();
   601→
   602→  // Increment calendar date by 1 day (instead of recalculating)
   603→  currentCalendarDate.setDate(currentCalendarDate.getDate() + 1);
   604→  totalSimulationDaysElapsed++;
   605→
   606→  // Update current day for display
   607→  currentDay = currentCalendarDate.getDate();
   608→
   609→  // Check if we've crossed into a new calendar month
   610→  const currentCalendarMonth = currentCalendarDate.getMonth();
   611→  const currentCalendarYear = currentCalendarDate.getFullYear();
   612→
   613→  const crossedIntoNewMonth =
   614→    (currentCalendarMonth !== previousCalendarMonth) ||
   615→    (currentCalendarYear !== previousCalendarYear);
   616→
   617→  if (crossedIntoNewMonth) {
   618→    // We've reached the 1st of a new calendar month - advance simulation
   619→    performStep();
   620→  }
   621→
   622→  // Send day update to UI
   623→  self.postMessage({
   624→    type: 'dayUpdate',
   625→    day: currentDay,
   626→    calendarDate: currentCalendarDate.toISOString()
   627→  } as WorkerResponse);
   628→}
   629→
   630→function handleSetSpeed(interval: number) {
   631→  stepInterval = interval;
   632→
   633→  // If running, restart loop with new interval
   634→  if (running && simulationIntervalId !== null) {
   635→    clearInterval(simulationIntervalId);
   636→    clearInterval(dayIntervalId!);
   637→    startSimulationLoop();
   638→  }
   639→}
   640→
   641→function handleDecision(decision: PlayerDecision) {
   642→  if (!state) {
   643→    throw new Error('Not initialized');
   644→  }
   645→
   646→  // Player decision injection - Queue for PlayerDecisionPhase (order 8.5)
   647→  // Initialize queue if not present
   648→  if (!state.playerDecisions) {
   649→    state.playerDecisions = [];
   650→  }
   651→
   652→  // Add decision to queue with timestamp
   653→  state.playerDecisions.push({
   654→    type: decision.type,
   655→    data: decision.data,
   656→    timestamp: state.currentMonth
   657→  });
   658→
   659→  console.log('[Worker] Player decision queued:', {
   660→    type: decision.type,
   661→    queueLength: state.playerDecisions.length,
   662→    timestamp: state.currentMonth
   663→  });
   664→
   665→  // Send acknowledgment to UI
   666→  self.postMessage({
   667→    type: 'decisionAck',
   668→    decisionType: decision.type,
   669→    queueLength: state.playerDecisions.length
   670→  } as WorkerResponse);
   671→}
   672→
   673→function startSimulationLoop() {
   674→  // Clear any existing intervals
   675→  if (simulationIntervalId !== null) {
   676→    clearInterval(simulationIntervalId);
   677→  }
   678→  if (dayIntervalId !== null) {
   679→    clearInterval(dayIntervalId);
   680→  }
   681→
   682→  if (!startDate) return;
   683→
   684→  // Track the current calendar month/year to detect when we cross into a new month
   685→  let lastCalendarMonth = new Date(startDate).getMonth();
   686→  let lastCalendarYear = new Date(startDate).getFullYear();
   687→
   688→  // Calculate how many milliseconds per simulation day based on stepInterval
   689→  // stepInterval is milliseconds per simulation month (default 30000ms = 30 seconds)
   690→  // So each simulation day should take stepInterval / 30 milliseconds
   691→  const msPerSimulationDay = stepInterval / 30;
   692→
   693→  // Start combined day counter and simulation stepper
   694→  dayIntervalId = setInterval(() => {
   695→    if (!running || !startDate || !state || !currentCalendarDate) {
   696→      if (dayIntervalId !== null) {
   697→        clearInterval(dayIntervalId);
   698→        dayIntervalId = null;
   699→      }
   700→      return;
   701→    }
   702→
   703→    // Track previous month/year for month-crossing detection
   704→    const previousCalendarMonth = currentCalendarDate.getMonth();
   705→    const previousCalendarYear = currentCalendarDate.getFullYear();
   706→
   707→    // Increment calendar date by 1 day (instead of recalculating)
   708→    currentCalendarDate.setDate(currentCalendarDate.getDate() + 1);
   709→    totalSimulationDaysElapsed++;
   710→
   711→    // Update current day for display
   712→    currentDay = currentCalendarDate.getDate();
   713→
   714→    // Check if we've crossed into a new calendar month
   715→    const currentCalendarMonth = currentCalendarDate.getMonth();
   716→    const currentCalendarYear = currentCalendarDate.getFullYear();
   717→
   718→    const crossedIntoNewMonth =
   719→      (currentCalendarMonth !== previousCalendarMonth) ||
   720→      (currentCalendarYear !== previousCalendarYear);
   721→
   722→    if (crossedIntoNewMonth) {
   723→      // We've reached the 1st of a new calendar month - advance simulation
   724→      lastCalendarMonth = currentCalendarMonth;
   725→      lastCalendarYear = currentCalendarYear;
   726→
   727→      // Perform simulation step
   728→      performStep();
   729→    }
   730→
   731→    // Send day update to UI
   732→    self.postMessage({
   733→      type: 'dayUpdate',
   734→      day: currentDay,
   735→      calendarDate: currentCalendarDate.toISOString()
   736→    } as WorkerResponse);
   737→  }, msPerSimulationDay); // Update based on simulation speed
