   740→function performStep() {
   741→  if (!engine || !state || !previousState) {
   742→    return;
   743→  }
   744→
   745→  // Run one simulation step (mutates state in place)
   746→  engine.step(state);
   747→
   748→  // Calculate delta (only changed fields, or all fields on first step)
   749→  const delta = calculateDelta(previousState, state);
   750→
   751→  // Reset first step flag after sending full delta
   752→  if (isFirstStep) {
   753→    isFirstStep = false;
   754→  }
   755→
   756→  // Update previous state snapshot
   757→  previousState = captureStateSnapshot(state);
   758→
   759→  // Clear event log after capturing snapshot to prevent re-sending old events
   760→  // This must happen AFTER captureStateSnapshot() to avoid state corruption
   761→  state.eventLog = [];
   762→
   763→  // Send update to main thread (use current calendar date directly)
   764→  self.postMessage({
   765→    type: 'update',
   766→    delta,
   767→    month: state.currentMonth,
   768→    day: currentDay,
   769→    calendarDate: currentCalendarDate?.toISOString() || new Date().toISOString(),
   770→    timestamp: Date.now()
   771→  } as WorkerResponse);
   772→}
