/**
 * Threshold Config Modal Section
 *
 * Compact version of threshold configuration for the initialization modal.
 * Shows research-backed threshold distributions with editing capability.
 */

'use client';

import { useState } from 'react';

interface ThresholdInfo {
  id: string;
  name: string;
  icon: string;
  description: string;
  defaultMin: number;
  defaultMax: number;
  defaultMode?: number;
  type: 'Normal' | 'Beta' | 'Triangular' | 'Uniform';
  unit: string;
}

const THRESHOLDS: ThresholdInfo[] = [
  // Tier 1: Empirical
  {
    id: 'climateSensitivity',
    name: 'Climate Sensitivity',
    icon: '🌍',
    description: 'Global temperature increase per CO₂ doubling. Controls climate tipping point timing.',
    defaultMin: 2.0,
    defaultMax: 5.0,
    type: 'Normal',
    unit: '°C'
  },
  {
    id: 'socialCriticalMass',
    name: 'Social Critical Mass',
    icon: '👥',
    description: 'Population fraction needed for social movements and norm changes to spread.',
    defaultMin: 0.20,
    defaultMax: 0.30,
    type: 'Normal',
    unit: ''
  },
  {
    id: 'trustRecoveryRate',
    name: 'Trust Recovery Rate',
    icon: '🛡️',
    description: 'How quickly society recovers trust in AI after failures or crises.',
    defaultMin: 0.005,
    defaultMax: 0.03,
    type: 'Beta',
    unit: '/mo'
  },
  {
    id: 'automationSpeed',
    name: 'Automation Speed',
    icon: '🤖',
    description: 'Rate at which AI automation displaces human labor across sectors.',
    defaultMin: 0.05,
    defaultMax: 0.30,
    type: 'Beta',
    unit: '/yr'
  },
  {
    id: 'detectionCeiling',
    name: 'Detection Ceiling',
    icon: '🔍',
    description: 'Maximum detection rate for AI deception (sandbagging) even with full investment.',
    defaultMin: 0.15,
    defaultMax: 0.35,
    type: 'Beta',
    unit: ''
  },
  // Tier 2: Historical
  {
    id: 'govLegitimacyCrisis',
    name: 'Gov Legitimacy Crisis',
    icon: '🏛️',
    description: 'Government legitimacy level triggering state collapse or revolution.',
    defaultMin: 0.25,
    defaultMode: 0.30,
    defaultMax: 0.40,
    type: 'Triangular',
    unit: ''
  },
  {
    id: 'surveillanceDystopia',
    name: 'Surveillance Dystopia',
    icon: '👁️',
    description: 'Surveillance intensity enabling stable authoritarian control over population.',
    defaultMin: 0.65,
    defaultMax: 0.80,
    type: 'Uniform',
    unit: ''
  },
  {
    id: 'unemploymentCrisis',
    name: 'Unemployment Crisis',
    icon: '📉',
    description: 'Unemployment rate (from AI automation) triggering social crisis and instability.',
    defaultMin: 0.40,
    defaultMode: 0.50,
    defaultMax: 0.60,
    type: 'Triangular',
    unit: ''
  },
  {
    id: 'aiRecursiveImprovement',
    name: 'AI Recursive Improvement',
    icon: '🔄',
    description: 'AI capability growth rate enabling recursive self-improvement (takeoff speed).',
    defaultMin: 1.2,
    defaultMax: 1.5,
    type: 'Uniform',
    unit: '×/mo'
  },
  {
    id: 'resentmentRevolt',
    name: 'Resentment Revolt',
    icon: '😡',
    description: 'Human resentment level (toward AI privilege/control) triggering mass revolt.',
    defaultMin: 0.60,
    defaultMode: 0.70,
    defaultMax: 0.80,
    type: 'Triangular',
    unit: ''
  },
];

export interface ThresholdOverrides {
  [key: string]: { min: number; max: number; mode?: number };
}

interface ThresholdConfigModalProps {
  overrides?: ThresholdOverrides;
  onChange?: (overrides: ThresholdOverrides | undefined) => void;
}

export function ThresholdConfigModal({ overrides, onChange }: ThresholdConfigModalProps) {
  const [expanded, setExpanded] = useState(false);

  const handleOverrideChange = (id: string, field: 'min' | 'max' | 'mode', value: number) => {
    if (!onChange) return;

    const currentOverrides = overrides || {};
    const threshold = THRESHOLDS.find(t => t.id === id);
    if (!threshold) return;

    const existingOverride = currentOverrides[id] || {
      min: threshold.defaultMin,
      max: threshold.defaultMax,
      mode: threshold.defaultMode
    };

    const newOverrides = {
      ...currentOverrides,
      [id]: {
        ...existingOverride,
        [field]: value
      }
    };

    onChange(newOverrides);
  };

  const handleResetToDefaults = () => {
    onChange?.(undefined);
  };

  const formatValue = (value: number, unit: string): string => {
    if (unit === '°C') return `${value.toFixed(1)}${unit}`;
    if (unit === '/mo' || unit === '/yr') return `${(value * 100).toFixed(1)}%${unit}`;
    if (unit === '×/mo') return `${value.toFixed(2)}${unit}`;
    if (unit === '') return `${(value * 100).toFixed(0)}%`;
    return value.toFixed(2);
  };

  const getEffectiveValue = (id: string, field: 'min' | 'max' | 'mode'): number => {
    const threshold = THRESHOLDS.find(t => t.id === id);
    if (!threshold) return 0;

    if (overrides?.[id]?.[field] !== undefined) {
      return overrides[id][field]!;
    }

    if (field === 'min') return threshold.defaultMin;
    if (field === 'max') return threshold.defaultMax;
    if (field === 'mode') return threshold.defaultMode || (threshold.defaultMin + threshold.defaultMax) / 2;
    return 0;
  };

  return (
    <div>
      <label className="block text-xs mb-2" style={{ color: 'var(--white-40)' }}>
        THRESHOLD UNCERTAINTY
        <button
          type="button"
          onClick={() => setExpanded(!expanded)}
          className="ml-2 text-cyan-400 hover:text-cyan-300"
        >
          [{expanded ? 'collapse' : 'view 10 thresholds'}]
        </button>
      </label>

      {!expanded ? (
        <div className="text-xs px-3 py-2 bg-black/50 border border-white/10 rounded" style={{ color: 'var(--white-60)' }}>
          {overrides && Object.keys(overrides).length > 0 ? (
            <>Custom distributions - {Object.keys(overrides).length} threshold{Object.keys(overrides).length > 1 ? 's' : ''} modified</>
          ) : (
            <>Research-backed distributions sampling epistemic uncertainty for 10 critical parameters</>
          )}
        </div>
      ) : (
        <div className="space-y-3 max-h-80 overflow-y-auto px-3 py-3 bg-black/50 border border-white/10 rounded">
          {/* Reset button */}
          {overrides && Object.keys(overrides).length > 0 && (
            <div className="flex items-center justify-end pb-2 border-b" style={{ borderColor: 'var(--white-10)' }}>
              <button
                type="button"
                onClick={handleResetToDefaults}
                className="text-xs px-2 py-1 bg-white/5 border border-white/20 text-white/60 hover:bg-white/10 rounded"
              >
                Reset All to Defaults
              </button>
            </div>
          )}

          {/* Threshold list */}
          {THRESHOLDS.map((threshold, idx) => {
            const effectiveMin = getEffectiveValue(threshold.id, 'min');
            const effectiveMax = getEffectiveValue(threshold.id, 'max');
            const effectiveMode = threshold.defaultMode !== undefined ? getEffectiveValue(threshold.id, 'mode') : undefined;
            const isModified = overrides?.[threshold.id] !== undefined;

            return (
              <div
                key={threshold.id}
                className="space-y-1 pb-2"
                style={{
                  borderBottom: idx < THRESHOLDS.length - 1 ? '1px solid var(--white-5)' : 'none'
                }}
              >
                {/* Threshold header */}
                <div className="space-y-1">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <span className="text-sm">{threshold.icon}</span>
                      <span
                        className="text-xs font-medium"
                        style={{ color: 'var(--white-80)' }}
                      >
                        {threshold.name}
                      </span>
                      {isModified && <span className="text-xs text-yellow-400" title="Modified from default">●</span>}
                    </div>
                    <div className="flex items-center gap-2">
                      <span style={{ color: 'var(--white-40)', fontSize: '0.7rem' }}>{threshold.type}</span>
                    </div>
                  </div>
                  <p className="text-xs" style={{ color: 'var(--white-50)', lineHeight: '1.4' }}>
                    {threshold.description}
                  </p>
                </div>

                {/* Range editors - always shown */}
                <div className="space-y-1 text-xs">
                  {/* Min */}
                  <div className="flex items-center gap-2">
                    <span style={{ color: 'var(--white-40)', minWidth: '35px' }}>Min:</span>
                    <input
                      type="number"
                      step={threshold.unit === '°C' ? 0.1 : 0.01}
                      value={effectiveMin}
                      onChange={(e) => handleOverrideChange(threshold.id, 'min', parseFloat(e.target.value))}
                      className="flex-1 bg-black border border-white/20 px-2 py-1 text-white rounded text-xs"
                    />
                    <span style={{ color: 'var(--white-60)', minWidth: '60px' }}>{formatValue(effectiveMin, threshold.unit)}</span>
                  </div>
                  {/* Mode (for triangular) */}
                  {threshold.defaultMode !== undefined && (
                    <div className="flex items-center gap-2">
                      <span style={{ color: 'var(--white-40)', minWidth: '35px' }}>Mode:</span>
                      <input
                        type="number"
                        step={0.01}
                        value={effectiveMode || 0}
                        onChange={(e) => handleOverrideChange(threshold.id, 'mode', parseFloat(e.target.value))}
                        className="flex-1 bg-black border border-white/20 px-2 py-1 text-white rounded text-xs"
                      />
                      <span style={{ color: 'var(--white-60)', minWidth: '60px' }}>{formatValue(effectiveMode || 0, threshold.unit)}</span>
                    </div>
                  )}
                  {/* Max */}
                  <div className="flex items-center gap-2">
                    <span style={{ color: 'var(--white-40)', minWidth: '35px' }}>Max:</span>
                    <input
                      type="number"
                      step={threshold.unit === '°C' ? 0.1 : 0.01}
                      value={effectiveMax}
                      onChange={(e) => handleOverrideChange(threshold.id, 'max', parseFloat(e.target.value))}
                      className="flex-1 bg-black border border-white/20 px-2 py-1 text-white rounded text-xs"
                    />
                    <span style={{ color: 'var(--white-60)', minWidth: '60px' }}>{formatValue(effectiveMax, threshold.unit)}</span>
                  </div>
                </div>
              </div>
            );
          })}

          <div className="text-xs pt-2 mt-2 border-t" style={{ color: 'var(--white-40)', borderColor: 'var(--white-10)' }}>
            💡 Each run samples new values from these distributions. Custom ranges should be backed by research.
          </div>
        </div>
      )}
    </div>
  );
}

