   101→
   102→        // Create simulations object store (v2+)
   103→        if (oldVersion < 2 && !db.objectStoreNames.contains(SIMULATIONS_STORE)) {
   104→          const simulationsStore = db.createObjectStore(SIMULATIONS_STORE, { keyPath: 'id' });
   105→
   106→          // Index by base simulationId for grouping saves
   107→          simulationsStore.createIndex('simulationId', 'simulationId', { unique: false });
   108→          // Index by lastUpdated for finding most recent save
   109→          simulationsStore.createIndex('lastUpdated', 'lastUpdated', { unique: false });
   110→
   111→          console.log('[EventDB] Simulations object store created with indexes');
   112→        }
   113→
   114→        // Create simulation_metadata object store (v2+)
   115→        if (oldVersion < 2 && !db.objectStoreNames.contains(METADATA_STORE)) {
   116→          const metadataStore = db.createObjectStore(METADATA_STORE, { keyPath: 'id' });
   117→
   118→          // Index by lastUpdated for sorting
   119→          metadataStore.createIndex('lastUpdated', 'lastUpdated', { unique: false });
   120→
   121→          console.log('[EventDB] Simulation metadata object store created');
   122→        }
   123→      };
   124→    });
   125→
   126→    return this.initPromise;
   127→  }
   128→
   129→  /**
   130→   * Add events to the database
   131→   */
   132→  async addEvents(simulationId: string, events: Omit<StoredEvent, 'simulationId' | 'insertedAt'>[]): Promise<void> {
   133→    await this.init();
   134→    if (!this.db) {
   135→      console.warn('[EventDB] Database not available, skipping storage');
   136→      return;
   137→    }
   138→
   139→    const transaction = this.db.transaction([STORE_NAME], 'readwrite');
   140→    const store = transaction.objectStore(STORE_NAME);
   141→    const now = Date.now();
   142→
   143→    for (const event of events) {
   144→      const storedEvent: StoredEvent = {
   145→        ...event,
   146→        simulationId,
   147→        insertedAt: now
   148→      };
   149→
   150→      // Use put instead of add to allow updates
   151→      store.put(storedEvent);
   152→    }
   153→
   154→    return new Promise((resolve, reject) => {
   155→      transaction.oncomplete = () => resolve();
   156→      transaction.onerror = () => reject(transaction.error);
   157→    });
   158→  }
   159→
   160→  /**
   161→   * Get events for a simulation run, paginated by timestamp
   162→   *
   163→   * @param simulationId - Simulation run ID
   164→   * @param limit - Number of events to fetch
   165→   * @param beforeTimestamp - Fetch events before this timestamp (for infinite scroll)
   166→   * @returns Events in reverse chronological order (newest first)
   167→   */
   168→  async getEvents(
   169→    simulationId: string,
   170→    limit: number = 50,
   171→    beforeTimestamp?: number
   172→  ): Promise<StoredEvent[]> {
   173→    await this.init();
   174→    if (!this.db) {
   175→      console.warn('[EventDB] Database not available');
   176→      return [];
   177→    }
   178→
   179→    const transaction = this.db.transaction([STORE_NAME], 'readonly');
   180→    const store = transaction.objectStore(STORE_NAME);
   181→    const index = store.index('simId_timestamp');
   182→
   183→    const events: StoredEvent[] = [];
   184→
   185→    // Create key range for this simulation
   186→    const keyRangeStart = [simulationId, 0];
   187→    const keyRangeEnd = beforeTimestamp !== undefined
   188→      ? [simulationId, beforeTimestamp]
   189→      : [simulationId, Number.MAX_SAFE_INTEGER];
   190→
   191→    // If beforeTimestamp is 0 or less, we can't create an exclusive upper bound
   192→    // because it would make start === end with an open bound, which is invalid
   193→    const upperOpen = beforeTimestamp !== undefined && beforeTimestamp > 0;
   194→    const range = IDBKeyRange.bound(keyRangeStart, keyRangeEnd, false, upperOpen);
   195→
   196→    return new Promise((resolve, reject) => {
   197→      const request = index.openCursor(range, 'prev'); // Reverse order (newest first)
   198→
   199→      request.onsuccess = (event) => {
   200→        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   201→
   202→        if (cursor && events.length < limit) {
   203→          events.push(cursor.value);
   204→          cursor.continue();
   205→        } else {
   206→          resolve(events);
   207→        }
   208→      };
   209→
   210→      request.onerror = () => {
   211→        console.error('[EventDB] Error fetching events:', request.error);
   212→        reject(request.error);
   213→      };
   214→    });
   215→  }
   216→
   217→  /**
   218→   * Get total event count for a simulation
   219→   */
   220→  async getEventCount(simulationId: string): Promise<number> {
   221→    await this.init();
   222→    if (!this.db) return 0;
   223→
   224→    const transaction = this.db.transaction([STORE_NAME], 'readonly');
   225→    const store = transaction.objectStore(STORE_NAME);
   226→    const index = store.index('simulationId');
   227→
   228→    return new Promise((resolve, reject) => {
   229→      const request = index.count(simulationId);
   230→      request.onsuccess = () => resolve(request.result);
   231→      request.onerror = () => reject(request.error);
   232→    });
   233→  }
   234→
   235→  /**
   236→   * Clear all events for a simulation run
   237→   */
   238→  async clearSimulation(simulationId: string): Promise<void> {
   239→    await this.init();
   240→    if (!this.db) return;
   241→
   242→    const transaction = this.db.transaction([STORE_NAME], 'readwrite');
   243→    const store = transaction.objectStore(STORE_NAME);
   244→    const index = store.index('simulationId');
   245→
   246→    return new Promise((resolve, reject) => {
   247→      const request = index.openCursor(IDBKeyRange.only(simulationId));
   248→
   249→      request.onsuccess = (event) => {
   250→        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   251→        if (cursor) {
   252→          cursor.delete();
   253→          cursor.continue();
   254→        } else {
   255→          resolve();
   256→        }
   257→      };
   258→
   259→      request.onerror = () => reject(request.error);
   260→    });
   261→  }
   262→
   263→  /**
   264→   * Clear entire database (all simulations)
   265→   */
   266→  async clearAll(): Promise<void> {
   267→    await this.init();
   268→    if (!this.db) return;
   269→
   270→    const transaction = this.db.transaction([STORE_NAME], 'readwrite');
   271→    const store = transaction.objectStore(STORE_NAME);
   272→
   273→    return new Promise((resolve, reject) => {
   274→      const request = store.clear();
   275→      request.onsuccess = () => resolve();
   276→      request.onerror = () => reject(request.error);
   277→    });
   278→  }
   279→
   280→  // ========================================================================
   281→  // Simulation State Persistence Methods
   282→  // ========================================================================
   283→
   284→  /**
   285→   * Save simulation state snapshot to IndexedDB
   286→   *
   287→   * @param simulationId - Base simulation ID (e.g., "42000_historical")
   288→   * @param state - Full GameState to save
   289→   * @param applyRotation - Whether to apply save rotation after saving (default: true)
   290→   */
   291→  async saveSimulation(simulationId: string, state: GameState, applyRotation: boolean = true): Promise<void> {
   292→    await this.init();
   293→    if (!this.db) {
   294→      console.warn('[EventDB] Database not available, skipping simulation save');
   295→      return;
   296→    }
   297→
   298→    try {
   299→      const now = Date.now();
   300→      const saveId = `${simulationId}_${state.currentMonth}`;
   301→
   302→      // Deep clone state to avoid mutation issues
   303→      const clonedState = JSON.parse(JSON.stringify(state)) as GameState;
   304→
   305→      const stored: StoredSimulation = {
   306→        id: saveId,
   307→        simulationId,
   308→        gameState: clonedState,
   309→        lastUpdated: now,
   310→        currentMonth: state.currentMonth,
   311→        version: SIMULATION_STATE_VERSION
   312→      };
   313→
   314→      // Save simulation state
   315→      const transaction = this.db.transaction([SIMULATIONS_STORE, METADATA_STORE], 'readwrite');
   316→      const simulationsStore = transaction.objectStore(SIMULATIONS_STORE);
   317→      const metadataStore = transaction.objectStore(METADATA_STORE);
   318→
   319→      simulationsStore.put(stored);
   320→
   321→      // Update metadata for listing
   322→      // Extract seed and scenario from simulationId (format: "{seed}_{scenario}")
   323→      const [seedStr, ...scenarioParts] = simulationId.split('_');
   324→      const seed = parseInt(seedStr, 10) || 0;
   325→      const scenario = scenarioParts.join('_') || 'historical';
   326→
   327→      const eventCount = await this.getEventCount(simulationId);
   328→      const metadata: SimulationMetadata = {
   329→        id: simulationId,
   330→        seed,
   331→        scenario: scenario as ScenarioMode,
   332→        // Use last updated time minus elapsed time as start date estimate
   333→        // For first save, this equals current timestamp (month 0)
   334→        // For subsequent saves, this approximates the original start time
   335→        startDate: new Date(now - (state.currentMonth * 30 * 24 * 60 * 60 * 1000)).toISOString(),
   336→        currentMonth: state.currentMonth,
   337→        lastUpdated: now,
   338→        eventCount,
   339→        isRunning: state.speed !== 'paused',
   340→        version: SIMULATION_STATE_VERSION,
   341→        population: state.humanPopulationSystem?.population || 0,
   342→        qualityOfLife: state.globalMetrics?.qualityOfLife || 0,
   343→        aiCapability: state.aiAgents.length > 0
   344→          ? state.aiAgents.reduce((sum, ai) => sum + (ai.capability || 0), 0) / state.aiAgents.length
   345→          : 0
   346→      };
   347→
   348→      metadataStore.put(metadata);
   349→
   350→      await new Promise<void>((resolve, reject) => {
   351→        transaction.oncomplete = () => {
   352→          console.log(`[EventDB] Saved simulation ${saveId}`);
   353→          resolve();
   354→        };
   355→        transaction.onerror = () => reject(transaction.error);
   356→      });
   357→
   358→      // Apply save rotation to prevent unbounded growth
   359→      if (applyRotation) {
   360→        await this.rotateSaves(simulationId);
   361→      }
   362→    } catch (error) {
   363→      console.error('[EventDB] Failed to save simulation:', error);
   364→      throw error;
   365→    }
   366→  }
   367→
   368→  /**
   369→   * Load simulation state from IndexedDB
   370→   *
   371→   * @param simulationId - Base simulation ID (e.g., "42000_historical")
   372→   * @returns Most recent save for this simulation, or null if not found
   373→   */
   374→  async loadSimulation(simulationId: string): Promise<StoredSimulation | null> {
   375→    await this.init();
   376→    if (!this.db) {
   377→      console.warn('[EventDB] Database not available');
   378→      return null;
   379→    }
   380→
   381→    try {
   382→      const transaction = this.db.transaction([SIMULATIONS_STORE], 'readonly');
   383→      const store = transaction.objectStore(SIMULATIONS_STORE);
   384→      const index = store.index('simulationId');
   385→
   386→      // Get all saves for this simulation, sorted by lastUpdated descending
   387→      const saves = await new Promise<StoredSimulation[]>((resolve, reject) => {
   388→        const results: StoredSimulation[] = [];
   389→        const request = index.openCursor(IDBKeyRange.only(simulationId), 'prev');
   390→
   391→        request.onsuccess = (event) => {
   392→          const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   393→          if (cursor) {
   394→            results.push(cursor.value as StoredSimulation);
   395→            cursor.continue();
   396→          } else {
   397→            resolve(results);
   398→          }
   399→        };
   400→
   401→        request.onerror = () => reject(request.error);
   402→      });
   403→
   404→      // Return most recent save
   405→      return saves.length > 0 ? saves[0] : null;
   406→    } catch (error) {
   407→      console.error('[EventDB] Failed to load simulation:', error);
   408→      return null;
   409→    }
   410→  }
   411→
   412→  /**
   413→   * List all simulations with metadata
   414→   *
   415→   * @returns Array of simulation metadata, sorted by lastUpdated descending
   416→   */
   417→  async listSimulations(): Promise<SimulationMetadata[]> {
   418→    await this.init();
   419→    if (!this.db) {
   420→      console.warn('[EventDB] Database not available');
   421→      return [];
   422→    }
   423→
   424→    try {
   425→      const transaction = this.db.transaction([METADATA_STORE], 'readonly');
   426→      const store = transaction.objectStore(METADATA_STORE);
   427→      const index = store.index('lastUpdated');
   428→
   429→      return new Promise((resolve, reject) => {
   430→        const results: SimulationMetadata[] = [];
   431→        const request = index.openCursor(null, 'prev'); // Descending order (newest first)
   432→
   433→        request.onsuccess = (event) => {
   434→          const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   435→          if (cursor) {
   436→            results.push(cursor.value as SimulationMetadata);
   437→            cursor.continue();
   438→          } else {
   439→            resolve(results);
   440→          }
   441→        };
   442→
   443→        request.onerror = () => reject(request.error);
   444→      });
   445→    } catch (error) {
   446→      console.error('[EventDB] Failed to list simulations:', error);
   447→      return [];
   448→    }
   449→  }
   450→
   451→  /**
   452→   * Delete a simulation and all its saves
   453→   *
   454→   * @param simulationId - Base simulation ID (e.g., "42000_historical")
   455→   */
   456→  async deleteSimulation(simulationId: string): Promise<void> {
   457→    await this.init();
   458→    if (!this.db) return;
   459→
   460→    try {
   461→      const transaction = this.db.transaction([SIMULATIONS_STORE, METADATA_STORE, STORE_NAME], 'readwrite');
   462→      const simulationsStore = transaction.objectStore(SIMULATIONS_STORE);
   463→      const metadataStore = transaction.objectStore(METADATA_STORE);
   464→      const eventsStore = transaction.objectStore(STORE_NAME);
   465→
   466→      // Delete all simulation saves
   467→      const simulationsIndex = simulationsStore.index('simulationId');
   468→      const simulationsCursor = simulationsIndex.openCursor(IDBKeyRange.only(simulationId));
   469→
   470→      simulationsCursor.onsuccess = (event) => {
   471→        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   472→        if (cursor) {
   473→          cursor.delete();
   474→          cursor.continue();
   475→        }
   476→      };
   477→
   478→      // Delete metadata
   479→      metadataStore.delete(simulationId);
   480→
