@import "tailwindcss";
@import "tw-animate-css";

/* ============================================
   FAR-FUTURE SIMULATION DASHBOARD
   Design System: Elysium-inspired, 2100s aesthetic
   Philosophy: High information density, pure black backgrounds, glowing accents
   Reference: /designs/00_design_system.md
   ============================================ */

:root {
  /* ====== Core Colors ====== */
  --color-black: #000000;
  --color-near-black: #0A0A0A;
  --color-white: #FFFFFF;

  /* ====== Accent Colors (Glowing) ====== */
  --color-cyan: #00F0FF;
  --color-blue: #0080FF;
  --color-amber: #FFB000;
  --color-orange: #FF6B00;
  --color-red: #FF0040;
  --color-green: #00FF88;
  --color-emerald: #00CC66;

  /* ====== Paradigm Colors ====== */
  --color-western-liberal: #00A0FF;
  --color-development: #00FF88;
  --color-ecological: #00CC66;
  --color-indigenous: #FF8800;

  /* ====== Opacity Variants ====== */
  --white-10: rgba(255, 255, 255, 0.1);
  --white-20: rgba(255, 255, 255, 0.2);
  --white-30: rgba(255, 255, 255, 0.3);
  --white-40: rgba(255, 255, 255, 0.4);
  --white-60: rgba(255, 255, 255, 0.6);

  /* ====== Glow Effects ====== */
  --glow-sm: 0 0 10px rgba(0, 240, 255, 0.1);
  --glow-md: 0 0 20px rgba(0, 240, 255, 0.2);
  --glow-lg: 0 0 40px rgba(0, 240, 255, 0.4);
  --glow-panel: 0 0 10px rgba(0, 240, 255, 0.1), inset 0 0 20px rgba(0, 240, 255, 0.02);
  --glow-active: 0 0 20px rgba(0, 240, 255, 0.4), 0 0 40px rgba(0, 240, 255, 0.2);
  --glow-alert: 0 0 20px rgba(255, 107, 0, 0.6);

  /* ====== Transitions ====== */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 300ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 500ms cubic-bezier(0.4, 0, 0.2, 1);

  /* ====== Typography ====== */
  --font-sans: 'Inter', 'SF Pro Display', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', monospace;

  /* ====== Spacing ====== */
  --space-panel-padding: 1.5rem;
  --space-panel-gap: 1rem;

  /* ====== Borders ====== */
  --border-panel: 1px solid var(--white-10);
  --border-active: 1px solid rgba(0, 240, 255, 0.6);
}

@layer base {
  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    background-color: var(--color-black);
    color: var(--color-white);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.5;
    overflow-x: hidden;
  }

  h1, h2, h3, h4, h5, h6 {
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--white-60);
  }

  h1 { font-size: 24px; }
  h2 { font-size: 18px; }
  h3 { font-size: 14px; }
  h4 { font-size: 12px; }

  /* Tabular numbers for metrics */
  .metric-value {
    font-variant-numeric: tabular-nums;
    font-weight: 200;
  }
}

@layer components {
  /* ====== Panel Component ====== */
  .panel {
    background-color: var(--color-near-black);
    border: var(--border-panel);
    box-shadow: var(--glow-panel);
    padding: var(--space-panel-padding);
    transition: all var(--transition-base);
  }

  .panel:hover {
    border-color: var(--white-20);
  }

  .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding-bottom: 0.75rem;
    border-bottom: var(--border-panel);
  }

  .panel-title {
    font-size: 13px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--white-60);
  }

  /* ====== Metric Card Component ====== */
  .metric-card {
    background-color: var(--color-near-black);
    border: var(--border-panel);
    padding: 1rem;
    transition: all var(--transition-fast);
  }

  .metric-card:hover {
    border-color: var(--white-30);
  }

  .metric-label {
    font-size: 11px;
    color: var(--white-40);
    margin-bottom: 0.5rem;
  }

  .metric-value {
    font-size: 32px;
    font-weight: 200;
    color: var(--color-white);
    font-variant-numeric: tabular-nums;
  }

  .metric-unit {
    font-size: 14px;
    color: var(--white-40);
    margin-left: 0.5rem;
  }

  /* ====== Status Indicators ====== */
  .status-indicator {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    display: inline-block;
  }

  .status-normal {
    background-color: var(--color-green);
    box-shadow: 0 0 8px var(--color-green);
  }

  .status-warning {
    background-color: var(--color-amber);
    box-shadow: 0 0 8px var(--color-amber);
  }

  .status-critical {
    background-color: var(--color-orange);
    box-shadow: 0 0 8px var(--color-orange);
    animation: pulse-glow 2s ease-in-out infinite;
  }

  .status-extinction {
    background-color: var(--color-red);
    box-shadow: 0 0 12px var(--color-red);
    animation: pulse-glow 1s ease-in-out infinite;
  }

  /* ====== Sparkline ====== */
  .sparkline {
    height: 32px;
    width: 100%;
  }

  .sparkline-path {
    fill: none;
    stroke: var(--color-cyan);
    stroke-width: 1.5px;
  }

  /* ====== Animations ====== */
  @keyframes pulse-glow {
    0%, 100% {
      opacity: 1;
      box-shadow: 0 0 8px currentColor;
    }
    50% {
      opacity: 0.6;
      box-shadow: 0 0 16px currentColor;
    }
  }

  @keyframes fade-in {
    from {
      opacity: 0;
      transform: translateY(4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* ====== Utility Classes ====== */
  .glow-cyan {
    box-shadow: var(--glow-active);
    border-color: rgba(0, 240, 255, 0.6);
  }

  .glow-amber {
    box-shadow: 0 0 20px rgba(255, 176, 0, 0.4);
    border-color: rgba(255, 176, 0, 0.6);
  }

  .glow-red {
    box-shadow: 0 0 20px rgba(255, 0, 64, 0.6);
    border-color: rgba(255, 0, 64, 0.8);
  }
}

