export interface InitialStateSnapshot {
  currentMonth: number;
  currentYear: number;
  qualityOfLife: number;
  population: number;
  aiCount: number;
  scenario: ScenarioMode;
}

type EventCallback = (...args: any[]) => void;

export class SimulationWorkerClient {
  private worker: Worker | null = null;
  private callbacks: Map<string, Set<EventCallback>> = new Map();
  private initialized = false;
  private running = false;

  constructor() {
    // Only create worker in browser environment
    if (typeof window === 'undefined' || typeof Worker === 'undefined') {
      console.warn('Web Workers not available (running in Node.js or unsupported browser)');
      return; // Don't throw - allow SSR to work
    }

    try {
      // Create worker from TypeScript file (Next.js handles bundling)
      // Note: Using dynamic import to avoid SSR issues
      this.worker = new Worker(
        new URL('../workers/simulationWorker.ts', import.meta.url),
        {
          type: 'module',
          name: 'simulation-worker'
        }
      );

      this.worker.addEventListener('message', this.handleMessage.bind(this));
      this.worker.addEventListener('error', this.handleError.bind(this));

      console.log('[Client] Web Worker created successfully');
    } catch (error) {
      console.error('[Client] Failed to create Web Worker:', error);
      this.worker = null;
      // Don't throw - allow component to render with error message
    }
  }

  private handleMessage(event: MessageEvent) {
    const msg = event.data;

    switch (msg.type) {
      case 'initialized':
        this.initialized = true;
        this.emit('initialized', msg.initialState, msg.startDate);
        break;

      case 'update':
        this.emit('update', msg.delta, msg.month, msg.day, msg.calendarDate, msg.timestamp);
        break;

      case 'dayUpdate':
        this.emit('dayUpdate', msg.day, msg.calendarDate);
        break;

      case 'paused':
        this.running = false;
        this.emit('paused', msg.month, msg.day);
        break;

      case 'resumed':
        this.running = true;
        this.emit('resumed', msg.month, msg.day);
        break;

      case 'error':
        this.emit('error', new Error(msg.error));
        break;

      default:
        console.warn('Unknown message type from worker:', msg.type);
    }
  }

  private handleError(event: ErrorEvent) {
    console.error('Worker error:', event);
    this.emit('error', event.error || new Error(event.message));
  }

  // Event emitter pattern
  on(event: string, callback: EventCallback): void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set());
    }
    this.callbacks.get(event)!.add(callback);
  }

  off(event: string, callback: EventCallback): void {
    this.callbacks.get(event)?.delete(callback);
  }

  once(event: string, callback: EventCallback): void {
    const wrappedCallback = (...args: any[]) => {
      callback(...args);
      this.off(event, wrappedCallback);
    };
    this.on(event, wrappedCallback);
  }

  private emit(event: string, ...args: any[]): void {
    this.callbacks.get(event)?.forEach(cb => {
      try {
        cb(...args);
      } catch (error) {
        console.error(`Error in ${event} callback:`, error);
      }
    });
  }

  // Public API

  /**
   * Initialize simulation with seed and scenario
   * @param seed - RNG seed for deterministic runs
   * @param scenario - 'historical' or 'unprecedented'
   * @param interval - Simulation step interval in milliseconds (default: 30000 = 1 month/30 seconds)
   * @param alignmentConfig - Optional alignment dynamics configuration
   * @param climatePriorityConfig - Optional government climate priority configuration
   */
  init(seed: number, scenario: ScenarioMode = 'historical', interval = 30000, alignmentConfig?: import('../types/alignment-dynamics').AlignmentDynamicsConfig, climatePriorityConfig?: import('../types/climate-priority').ClimatePriorityConfig, thresholdOverrides?: import('../components/thresholds/ThresholdConfigModal').ThresholdOverrides): void {
    if (this.initialized) {
      throw new Error('Already initialized. Create a new client to reinitialize.');
    }

    if (!this.worker) {
      throw new Error('Worker not available. Check browser console for errors. Web Workers may not be supported in this environment.');
    }

    console.log('[Client] Initializing worker with seed:', seed, 'scenario:', scenario, 'alignment:', alignmentConfig ? 'custom' : 'default', 'climate:', climatePriorityConfig?.preset || 'baseline', 'thresholds:', thresholdOverrides ? 'custom' : 'defaults');

    this.worker.postMessage({
      type: 'init',
      seed,
      scenario,
      interval,
      alignmentConfig,
      climatePriorityConfig,
      thresholdOverrides
    });
  }

  /**
   * Start simulation (auto-steps at configured interval)
   */
  start(): void {
    if (!this.initialized) {
      throw new Error('Not initialized. Call init() first.');
    }

    if (this.running) {
      console.warn('Simulation already running');
      return;
    }

    this.worker?.postMessage({ type: 'start' });
    this.running = true;
  }

  /**
   * Pause simulation
   */
  pause(): void {
    if (!this.running) {
      console.warn('Simulation not running');
      return;
    }

    this.worker?.postMessage({ type: 'pause' });
  }

  /**
   * Resume simulation after pause
   */
  resume(): void {
    if (this.running) {
      console.warn('Simulation already running');
      return;
    }

    if (!this.initialized) {
      throw new Error('Not initialized. Call init() first.');
    }

    this.worker?.postMessage({ type: 'resume' });
  }

  /**
   * Manually step simulation once (useful when paused)
   */
  step(): void {
    if (!this.initialized) {
      throw new Error('Not initialized. Call init() first.');
    }

    this.worker?.postMessage({ type: 'step' });
  }

  /**
   * Change simulation speed
   * @param interval - Step interval in milliseconds
   */
  setSpeed(interval: number): void {
    if (!this.initialized) {
      throw new Error('Not initialized. Call init() first.');
    }

    this.worker?.postMessage({ type: 'setSpeed', interval });
  }

  /**
   * Inject player decision (Phase 3 - future work)
   * @param decision - Player decision to inject
   */
  decision(decision: any): void {
    if (!this.initialized) {
      throw new Error('Not initialized. Call init() first.');
    }

    this.worker?.postMessage({ type: 'decision', decision });
  }

  /**
   * Terminate worker and clean up
   */
  destroy(): void {
    if (this.worker) {
      this.worker.terminate();
      this.worker = null;
    }
    this.callbacks.clear();
    this.initialized = false;
    this.running = false;
  }

  // Getters
  isInitialized(): boolean {
    return this.initialized;
  }

  isRunning(): boolean {
    return this.running;
  }
}

// Helper hook for React (optional)
export function useSimulationWorker() {
  if (typeof window === 'undefined') {
    return null; // SSR guard
  }

  // Client-side only
  return new SimulationWorkerClient();
}

/**
 * Simulation Worker Context
 *
 * Global singleton for managing the simulation Web Worker.
 * Ensures only ONE worker instance exists across the entire app.
 * Provides shared state to Navigation and all dashboard pages.
 *
 * Architecture:
 * - Single worker created on app mount
 * - Shared state distributed via React Context
 * - Components subscribe to updates without creating duplicate workers
 * - Proper cleanup on app unmount only
 */

'use client'

import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import { SimulationWorkerClient, type StateDelta, type InitialStateSnapshot } from '@/lib/simulationWorkerClient'
import type { ScenarioMode } from '@/types/game'

interface SimulationWorkerContextValue {
  // Worker client (singleton)
  client: SimulationWorkerClient | null

  // Simulation state
  initialized: boolean
  running: boolean
  month: number  // UI display month (for formatted date)
  day: number    // UI display day (for formatted date)
  year: number   // UI display year (for formatted date)
  simulationMonth: number  // Actual simulation month (0, 1, 2...)
  simulationDay: number    // Actual simulation day (1-30)
  scenario: ScenarioMode
  seed: number
  startDate: Date | null  // Real-world date when simulation started

  // Latest update delta (for pages that need detailed state)
  lastUpdate: StateDelta | null

  // Control functions
  init: (seed: number, scenario: ScenarioMode, speed: number, alignmentConfig?: import('@/types/alignment-dynamics').AlignmentDynamicsConfig, climatePriorityConfig?: import('@/types/climate-priority').ClimatePriorityConfig, thresholdOverrides?: import('@/components/thresholds/ThresholdConfigModal').ThresholdOverrides) => void
  start: () => void
  pause: () => void
  step: () => void
}

const SimulationWorkerContext = createContext<SimulationWorkerContextValue | null>(null)

export function SimulationWorkerProvider({ children }: { children: ReactNode }) {
  // Use ref to ensure worker persists across re-renders
  const clientRef = useRef<SimulationWorkerClient | null>(null)

  // Simulation state (actual month/day in the simulation)
  const [initialized, setInitialized] = useState(false)
  const [running, setRunning] = useState(false)
  const [simulationMonth, setSimulationMonth] = useState(0)
  const [simulationDay, setSimulationDay] = useState(1)
  const [scenario, setScenario] = useState<ScenarioMode>('historical')
  const [seed, setSeed] = useState(42000)
  const [lastUpdate, setLastUpdate] = useState<StateDelta | null>(null)

  // UI-only date display (doesn't affect simulation state)
  const [displayDate, setDisplayDate] = useState<Date>(new Date())

  // Create singleton worker on mount
  useEffect(() => {
    if (typeof window === 'undefined') return

    // Only create if doesn't exist
    if (!clientRef.current) {
      try {
        const client = new SimulationWorkerClient()
        clientRef.current = client

        console.log('[WorkerContext] Created singleton worker client')

        // Setup global listeners
        client.on('initialized', (snapshot: InitialStateSnapshot, startDate?: string) => {
          console.log('[WorkerContext] Worker initialized:', snapshot)
          setInitialized(true)
          setSimulationMonth(snapshot.currentMonth)
          setScenario(snapshot.scenario)

          // Set UI display date to today's real-world date
          if (startDate) {
            setDisplayDate(new Date(startDate))
          } else {
            setDisplayDate(new Date())
          }
        })

        client.on('update', (delta: StateDelta, currentMonth?: number, currentDay?: number) => {
          setLastUpdate(delta)
          if (delta.currentMonth !== undefined) {
            setSimulationMonth(delta.currentMonth)
          }
          if (currentDay !== undefined) {
            setSimulationDay(currentDay)
          }
        })

        client.on('dayUpdate', (currentDay: number) => {
          setSimulationDay(currentDay)

          // Increment UI display date by 1 day (purely cosmetic)
          setDisplayDate(prevDate => {
            const newDate = new Date(prevDate)
            newDate.setDate(newDate.getDate() + 1)
            return newDate
          })
        })

        client.on('paused', () => {
          console.log('[WorkerContext] Simulation paused')
          setRunning(false)
        })

        client.on('resumed', () => {
          console.log('[WorkerContext] Simulation resumed')
          setRunning(true)
        })

        client.on('error', (error: Error) => {
          console.error('[WorkerContext] Worker error:', error)
        })
      } catch (error) {
        console.error('[WorkerContext] Failed to create worker:', error)
      }
    }

    // Cleanup only on app unmount (not on re-render)
    return () => {
      console.log('[WorkerContext] App unmounting, destroying worker')
      if (clientRef.current) {
        clientRef.current.destroy()
        clientRef.current = null
      }
    }
  }, []) // Empty deps - only run on mount/unmount

  // Control functions
  const init = (seedValue: number, scenarioValue: ScenarioMode, speed: number, alignmentConfig?: import('@/types/alignment-dynamics').AlignmentDynamicsConfig, climatePriorityConfig?: import('@/types/climate-priority').ClimatePriorityConfig, thresholdOverrides?: import('@/components/thresholds/ThresholdConfigModal').ThresholdOverrides) => {
    if (!clientRef.current) {
      console.error('[WorkerContext] Cannot init: no worker client')
      return
    }

    if (initialized) {
      console.warn('[WorkerContext] Already initialized')
      return
    }

    setSeed(seedValue)
    setScenario(scenarioValue)

    const interval = Math.floor(30000 / speed)
    clientRef.current.init(seedValue, scenarioValue, interval, alignmentConfig, climatePriorityConfig, thresholdOverrides)
