  const init = (seedValue: number, scenarioValue: ScenarioMode, speed: number, alignmentConfig?: import('@/types/alignment-dynamics').AlignmentDynamicsConfig, climatePriorityConfig?: import('@/types/climate-priority').ClimatePriorityConfig, thresholdOverrides?: import('@/components/thresholds/ThresholdConfigModal').ThresholdOverrides) => {
