     1→/**
     2→ * IndexedDB wrapper for persistent event storage and simulation state persistence
     3→ *
     4→ * Stores all simulation events across runs for infinite scroll timeline.
     5→ * Also stores full GameState snapshots for resume/continue functionality.
     6→ * Events are indexed by simulation run and timestamp for efficient querying.
     7→ */
     8→
     9→import type { GameState, ScenarioMode } from '@/types/game';
    10→
    11→interface StoredEvent {
    12→  id: string;                 // Unique event ID
    13→  simulationId: string;       // Simulation run ID (seed + scenario)
    14→  timestamp: number;          // Month when event occurred
    15→  type: string;
    16→  category: string;
    17→  description: string;
    18→  severity: 'low' | 'medium' | 'high' | 'critical';
    19→  insertedAt: number;         // Real-world timestamp when stored
    20→}
    21→
    22→interface StoredSimulation {
    23→  id: string;                    // `${seed}_${scenario}_${month}`
    24→  simulationId: string;          // `${seed}_${scenario}` (base ID for grouping)
    25→  gameState: GameState;          // Full simulation state
    26→  lastUpdated: number;           // Timestamp of last save
    27→  currentMonth: number;          // Quick access to progress
    28→  version: string;               // Semantic version for migrations (MAJOR.MINOR.PATCH)
    29→}
    30→
    31→interface SimulationMetadata {
    32→  id: string;                    // Unique metadata ID (same as base simulationId)
    33→  seed: number;
    34→  scenario: ScenarioMode;
    35→  startDate: string;
    36→  currentMonth: number;
    37→  lastUpdated: number;
    38→  eventCount: number;
    39→  isRunning: boolean;            // Paused vs running
    40→  version: string;               // Schema version
    41→  population: number;            // Current population (for display)
    42→  qualityOfLife: number;         // Current QoL (for display)
    43→  aiCapability: number;          // Average AI capability (for display)
    44→}
    45→
    46→const DB_NAME = 'simulation_events';
    47→const DB_VERSION = 2;  // Incremented for new object stores
    48→const STORE_NAME = 'events';
    49→const SIMULATIONS_STORE = 'simulations';
    50→const METADATA_STORE = 'simulation_metadata';
    51→
    52→// Semantic versioning for simulation state schema
    53→const SIMULATION_STATE_VERSION = '1.0.0';
    54→
    55→/**
    56→ * Parse semantic version string into comparable components
    57→ */
    58→function parseVersion(version: string): { major: number; minor: number; patch: number } {
    59→  const [major, minor, patch] = version.split('.').map(Number);
    60→  return { major: major || 0, minor: minor || 0, patch: patch || 0 };
    61→}
    62→
    63→/**
    64→ * Check if version is compatible
    65→ * - MAJOR version change: Breaking changes, cannot resume (data structure changed)
    66→ * - MINOR version change: New features, backward compatible (can resume with warnings)
    67→ * - PATCH version change: Bug fixes, fully compatible (can resume seamlessly)
    68→ */
    69→function isVersionCompatible(savedVersion: string, currentVersion: string): {
    70→  compatible: boolean;
    71→  requiresMigration: boolean;
    72→  canResume: boolean;
    73→  reason?: string;
    74→} {
    75→  const saved = parseVersion(savedVersion);
    76→  const current = parseVersion(currentVersion);
    77→
    78→  // Major version mismatch = breaking changes
    79→  if (saved.major !== current.major) {
    80→    return {
    81→      compatible: false,
    82→      requiresMigration: false,
    83→      canResume: false,
    84→      reason: `Major version mismatch: saved v${savedVersion}, current v${currentVersion}. Breaking changes prevent resume.`
    85→    };
    86→  }
    87→
    88→  // Minor version older = might need migration
    89→  if (saved.minor < current.minor) {
    90→    return {
    91→      compatible: true,
    92→      requiresMigration: true,
    93→      canResume: true,
    94→      reason: `Minor version upgrade: saved v${savedVersion}, current v${currentVersion}. Migration will be applied.`
    95→    };
    96→  }
    97→
    98→  // Same major.minor = fully compatible
    99→  return { compatible: true, requiresMigration: false, canResume: true };
   100→}
   101→
   102→/**
   103→ * Example migration: Add RNG call counter to old saves
   104→ */
   105→function migrate_1_0_to_1_1(state: any): any {
   106→  if (state.rngCallCounter === undefined) {
   107→    // Estimate RNG calls based on current month (approximate)
   108→    state.rngCallCounter = state.currentMonth * 100; // Rough estimate
   109→    console.warn('[Migration] RNG call counter estimated - determinism may be slightly affected');
   110→  }
   111→  return state;
   112→}
   113→
   114→/**
   115→ * Migration functions for version upgrades
   116→ */
   117→async function migrateSimulationState(stored: StoredSimulation, targetVersion: string): Promise<StoredSimulation> {
   118→  const currentVersion = parseVersion(stored.version);
   119→  const target = parseVersion(targetVersion);
   120→
   121→  let state = stored.gameState;
   122→
   123→  // Apply migrations sequentially
   124→  if (currentVersion.major === 1 && currentVersion.minor === 0) {
   125→    // Migrate 1.0.x → 1.1.0: Add rngCallCounter
   126→    if (target.minor >= 1) {
   127→      state = migrate_1_0_to_1_1(state);
   128→      stored.version = '1.1.0';
   129→    }
   130→  }
   131→
   132→  // Future migrations go here
   133→  // if (currentVersion.major === 1 && currentVersion.minor === 1) {
   134→  //   if (target.minor >= 2) {
   135→  //     state = migrate_1_1_to_1_2(state);
   136→  //     stored.version = '1.2.0';
   137→  //   }
   138→  // }
   139→
   140→  stored.gameState = state;
   141→  return stored;
   142→}
   143→
   144→class EventDatabase {
   145→  private db: IDBDatabase | null = null;
   146→  private initPromise: Promise<void> | null = null;
   147→
   148→  /**
   149→   * Initialize IndexedDB connection
   150→   */
   151→  async init(): Promise<void> {
   152→    if (this.db) return; // Already initialized
   153→    if (this.initPromise) return this.initPromise; // Initialization in progress
   154→
   155→    this.initPromise = new Promise((resolve, reject) => {
   156→      if (typeof window === 'undefined' || !window.indexedDB) {
   157→        console.warn('[EventDB] IndexedDB not available (SSR or unsupported browser)');
   158→        resolve();
   159→        return;
   160→      }
   161→
   162→      const request = indexedDB.open(DB_NAME, DB_VERSION);
   163→
   164→      request.onerror = () => {
   165→        console.error('[EventDB] Failed to open database:', request.error);
   166→        reject(request.error);
   167→      };
   168→
   169→      request.onsuccess = () => {
   170→        this.db = request.result;
   171→        console.log('[EventDB] Database opened successfully');
   172→        resolve();
   173→      };
   174→
   175→      request.onupgradeneeded = (event) => {
   176→        const db = (event.target as IDBOpenDBRequest).result;
   177→        const oldVersion = event.oldVersion;
   178→
   179→        // Create events object store if it doesn't exist
   180→        if (!db.objectStoreNames.contains(STORE_NAME)) {
   181→          const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
   182→
   183→          // Create indexes for efficient querying
   184→          store.createIndex('simulationId', 'simulationId', { unique: false });
   185→          store.createIndex('timestamp', 'timestamp', { unique: false });
   186→          store.createIndex('simId_timestamp', ['simulationId', 'timestamp'], { unique: false });
   187→
   188→          console.log('[EventDB] Events object store created with indexes');
   189→        }
   190→
   191→        // Create simulations object store (v2+)
   192→        if (oldVersion < 2 && !db.objectStoreNames.contains(SIMULATIONS_STORE)) {
   193→          const simulationsStore = db.createObjectStore(SIMULATIONS_STORE, { keyPath: 'id' });
   194→
   195→          // Index by base simulationId for grouping saves
   196→          simulationsStore.createIndex('simulationId', 'simulationId', { unique: false });
   197→          // Index by lastUpdated for finding most recent save
   198→          simulationsStore.createIndex('lastUpdated', 'lastUpdated', { unique: false });
   199→
   200→          console.log('[EventDB] Simulations object store created with indexes');
   201→        }
   202→
   203→        // Create simulation_metadata object store (v2+)
   204→        if (oldVersion < 2 && !db.objectStoreNames.contains(METADATA_STORE)) {
   205→          const metadataStore = db.createObjectStore(METADATA_STORE, { keyPath: 'id' });
   206→
   207→          // Index by lastUpdated for sorting
   208→          metadataStore.createIndex('lastUpdated', 'lastUpdated', { unique: false });
   209→
   210→          console.log('[EventDB] Simulation metadata object store created');
   211→        }
   212→      };
   213→    });
   214→
   215→    return this.initPromise;
   216→  }
   217→
   218→  /**
   219→   * Add events to the database
   220→   */
   221→  async addEvents(simulationId: string, events: Omit<StoredEvent, 'simulationId' | 'insertedAt'>[]): Promise<void> {
   222→    await this.init();
   223→    if (!this.db) {
   224→      console.warn('[EventDB] Database not available, skipping storage');
   225→      return;
   226→    }
   227→
   228→    const transaction = this.db.transaction([STORE_NAME], 'readwrite');
   229→    const store = transaction.objectStore(STORE_NAME);
   230→    const now = Date.now();
   231→
   232→    for (const event of events) {
   233→      const storedEvent: StoredEvent = {
   234→        ...event,
   235→        simulationId,
   236→        insertedAt: now
   237→      };
   238→
   239→      // Use put instead of add to allow updates
   240→      store.put(storedEvent);
   241→    }
   242→
   243→    return new Promise((resolve, reject) => {
   244→      transaction.oncomplete = () => resolve();
   245→      transaction.onerror = () => reject(transaction.error);
   246→    });
   247→  }
   248→
   249→  /**
   250→   * Get events for a simulation run, paginated by timestamp
   251→   *
   252→   * @param simulationId - Simulation run ID
   253→   * @param limit - Number of events to fetch
   254→   * @param beforeTimestamp - Fetch events before this timestamp (for infinite scroll)
   255→   * @returns Events in reverse chronological order (newest first)
   256→   */
   257→  async getEvents(
   258→    simulationId: string,
   259→    limit: number = 50,
   260→    beforeTimestamp?: number
   261→  ): Promise<StoredEvent[]> {
   262→    await this.init();
   263→    if (!this.db) {
   264→      console.warn('[EventDB] Database not available');
   265→      return [];
   266→    }
   267→
   268→    const transaction = this.db.transaction([STORE_NAME], 'readonly');
   269→    const store = transaction.objectStore(STORE_NAME);
   270→    const index = store.index('simId_timestamp');
   271→
   272→    const events: StoredEvent[] = [];
   273→
   274→    // Create key range for this simulation
   275→    const keyRangeStart = [simulationId, 0];
   276→    const keyRangeEnd = beforeTimestamp !== undefined
   277→      ? [simulationId, beforeTimestamp]
   278→      : [simulationId, Number.MAX_SAFE_INTEGER];
   279→
   280→    // If beforeTimestamp is 0 or less, we can't create an exclusive upper bound
   281→    // because it would make start === end with an open bound, which is invalid
   282→    const upperOpen = beforeTimestamp !== undefined && beforeTimestamp > 0;
   283→    const range = IDBKeyRange.bound(keyRangeStart, keyRangeEnd, false, upperOpen);
   284→
   285→    return new Promise((resolve, reject) => {
   286→      const request = index.openCursor(range, 'prev'); // Reverse order (newest first)
   287→
   288→      request.onsuccess = (event) => {
   289→        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   290→
   291→        if (cursor && events.length < limit) {
   292→          events.push(cursor.value);
   293→          cursor.continue();
   294→        } else {
   295→          resolve(events);
   296→        }
   297→      };
   298→
   299→      request.onerror = () => {
