   327→  async clearSimulation(simulationId: string): Promise<void> {
   328→    await this.init();
   329→    if (!this.db) return;
   330→
   331→    const transaction = this.db.transaction([STORE_NAME], 'readwrite');
   332→    const store = transaction.objectStore(STORE_NAME);
