   368→
   369→  // ========================================================================
   370→  // Simulation State Persistence Methods
   371→  // ========================================================================
   372→
   373→  /**
   374→   * Save simulation state snapshot to IndexedDB
   375→   *
   376→   * @param simulationId - Base simulation ID (e.g., "42000_historical")
   377→   * @param state - Full GameState to save
   378→   * @param applyRotation - Whether to apply save rotation after saving (default: true)
   379→   */
   380→  async saveSimulation(simulationId: string, state: GameState, applyRotation: boolean = true): Promise<void> {
   381→    await this.init();
   382→    if (!this.db) {
   383→      console.warn('[EventDB] Database not available, skipping simulation save');
   384→      return;
   385→    }
   386→
   387→    try {
   388→      const now = Date.now();
   389→      const saveId = `${simulationId}_${state.currentMonth}`;
   390→
   391→      // Deep clone state to avoid mutation issues
   392→      const clonedState = JSON.parse(JSON.stringify(state)) as GameState;
   393→
   394→      // Check storage space before saving
   395→      const estimatedSize = this.estimateStorageSize(clonedState);
   396→      const spaceCheck = await this.checkStorageSpace(estimatedSize);
   397→
   398→      if (!spaceCheck.canSave) {
   399→        console.error('[EventDB] Insufficient storage space:', spaceCheck.warning);
   400→        throw new Error(spaceCheck.warning || 'Storage quota exceeded');
   401→      }
   402→
   403→      if (spaceCheck.warning) {
   404→        console.warn('[EventDB] Storage warning:', spaceCheck.warning);
   405→      }
   406→
   407→      const stored: StoredSimulation = {
   408→        id: saveId,
   409→        simulationId,
   410→        gameState: clonedState,
   411→        lastUpdated: now,
   412→        currentMonth: state.currentMonth,
   413→        version: SIMULATION_STATE_VERSION
   414→      };
   415→
   416→      // Save simulation state
   417→      const transaction = this.db.transaction([SIMULATIONS_STORE, METADATA_STORE], 'readwrite');
   418→      const simulationsStore = transaction.objectStore(SIMULATIONS_STORE);
   419→      const metadataStore = transaction.objectStore(METADATA_STORE);
   420→
   421→      simulationsStore.put(stored);
   422→
   423→      // Update metadata for listing
   424→      // Extract seed and scenario from simulationId (format: "{seed}_{scenario}")
   425→      const [seedStr, ...scenarioParts] = simulationId.split('_');
   426→      const seed = parseInt(seedStr, 10) || 0;
   427→      const scenario = scenarioParts.join('_') || 'historical';
   428→
   429→      const eventCount = await this.getEventCount(simulationId);
   430→      const metadata: SimulationMetadata = {
   431→        id: simulationId,
   432→        seed,
   433→        scenario: scenario as ScenarioMode,
   434→        // Use last updated time minus elapsed time as start date estimate
   435→        // For first save, this equals current timestamp (month 0)
   436→        // For subsequent saves, this approximates the original start time
   437→        startDate: new Date(now - (state.currentMonth * 30 * 24 * 60 * 60 * 1000)).toISOString(),
   438→        currentMonth: state.currentMonth,
   439→        lastUpdated: now,
   440→        eventCount,
   441→        isRunning: state.speed !== 'paused',
   442→        version: SIMULATION_STATE_VERSION,
   443→        population: state.humanPopulationSystem?.population || 0,
   444→        qualityOfLife: state.globalMetrics?.qualityOfLife || 0,
   445→        aiCapability: state.aiAgents.length > 0
   446→          ? state.aiAgents.reduce((sum, ai) => sum + (ai.capability || 0), 0) / state.aiAgents.length
   447→          : 0
   448→      };
   449→
   450→      metadataStore.put(metadata);
   451→
   452→      await new Promise<void>((resolve, reject) => {
   453→        transaction.oncomplete = () => {
   454→          console.log(`[EventDB] Saved simulation ${saveId}`);
   455→          resolve();
   456→        };
   457→        transaction.onerror = () => reject(transaction.error);
   458→      });
   459→
   460→      // Apply save rotation to prevent unbounded growth
   461→      if (applyRotation) {
   462→        await this.rotateSaves(simulationId);
   463→      }
   464→    } catch (error) {
   465→      console.error('[EventDB] Failed to save simulation:', error);
   466→      throw error;
   467→    }
   468→  }
   469→
   470→  /**
   471→   * Load simulation state from IndexedDB with version compatibility checking and migration
   472→   *
   473→   * @param simulationId - Base simulation ID (e.g., "42000_historical")
   474→   * @returns Most recent save for this simulation, or null if not found
   475→   * @throws Error if version is incompatible and cannot be migrated
   476→   */
   477→  async loadSimulation(simulationId: string): Promise<StoredSimulation | null> {
   478→    await this.init();
   479→    if (!this.db) {
   480→      console.warn('[EventDB] Database not available');
   481→      return null;
   482→    }
   483→
   484→    try {
   485→      const transaction = this.db.transaction([SIMULATIONS_STORE], 'readonly');
   486→      const store = transaction.objectStore(SIMULATIONS_STORE);
   487→      const index = store.index('simulationId');
   488→
   489→      // Get all saves for this simulation, sorted by lastUpdated descending
   490→      const saves = await new Promise<StoredSimulation[]>((resolve, reject) => {
   491→        const results: StoredSimulation[] = [];
   492→        const request = index.openCursor(IDBKeyRange.only(simulationId), 'prev');
   493→
   494→        request.onsuccess = (event) => {
   495→          const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   496→          if (cursor) {
   497→            results.push(cursor.value as StoredSimulation);
   498→            cursor.continue();
   499→          } else {
   500→            resolve(results);
   501→          }
   502→        };
   503→
   504→        request.onerror = () => reject(request.error);
   505→      });
   506→
   507→      if (saves.length === 0) {
   508→        return null;
   509→      }
   510→
   511→      // Get most recent save
   512→      let stored = saves[0];
   513→
   514→      // Validate critical fields (detect corrupted state)
   515→      if (!stored.gameState || typeof stored.gameState !== 'object') {
   516→        console.error('[EventDB] Corrupted simulation: missing or invalid gameState');
   517→        throw new Error('Simulation data is corrupted (invalid gameState)');
   518→      }
   519→
   520→      if (stored.gameState.currentMonth === undefined || stored.gameState.currentMonth === null) {
   521→        console.error('[EventDB] Corrupted simulation: missing currentMonth');
   522→        throw new Error('Simulation data is corrupted (missing currentMonth)');
   523→      }
   524→
   525→      if (!stored.gameState.globalMetrics) {
   526→        console.error('[EventDB] Corrupted simulation: missing globalMetrics');
   527→        throw new Error('Simulation data is corrupted (missing globalMetrics)');
   528→      }
   529→
   530→      // Check version compatibility
   531→      const compatibility = isVersionCompatible(stored.version, SIMULATION_STATE_VERSION);
   532→
   533→      if (!compatibility.canResume) {
   534→        console.error('[EventDB] Incompatible version:', compatibility.reason);
   535→        throw new Error(compatibility.reason || 'Incompatible simulation version');
   536→      }
   537→
   538→      // Apply migration if needed
   539→      if (compatibility.requiresMigration) {
   540→        console.log('[EventDB] Migrating simulation from', stored.version, 'to', SIMULATION_STATE_VERSION);
   541→        stored = await migrateSimulationState(stored, SIMULATION_STATE_VERSION);
   542→
   543→        // Save migrated state back to database
   544→        const writeTransaction = this.db.transaction([SIMULATIONS_STORE], 'readwrite');
   545→        const writeStore = writeTransaction.objectStore(SIMULATIONS_STORE);
   546→        writeStore.put(stored);
   547→
   548→        await new Promise<void>((resolve, reject) => {
   549→          writeTransaction.oncomplete = () => resolve();
   550→          writeTransaction.onerror = () => reject(writeTransaction.error);
   551→        });
   552→
   553→        console.log('[EventDB] Migration complete, saved updated state');
   554→      }
   555→
   556→      return stored;
   557→    } catch (error) {
   558→      console.error('[EventDB] Failed to load simulation:', error);
   559→      if (error instanceof Error && error.message.includes('version')) {
   560→        throw error; // Re-throw version errors for UI to handle
   561→      }
   562→      return null;
   563→    }
   564→  }
   565→
   566→  /**
   567→   * List all simulations with metadata
   568→   *
   569→   * @returns Array of simulation metadata, sorted by lastUpdated descending
   570→   */
   571→  async listSimulations(): Promise<SimulationMetadata[]> {
   572→    await this.init();
   573→    if (!this.db) {
   574→      console.warn('[EventDB] Database not available');
   575→      return [];
   576→    }
   577→
   578→    try {
   579→      const transaction = this.db.transaction([METADATA_STORE], 'readonly');
   580→      const store = transaction.objectStore(METADATA_STORE);
   581→      const index = store.index('lastUpdated');
   582→
   583→      return new Promise((resolve, reject) => {
   584→        const results: SimulationMetadata[] = [];
   585→        const request = index.openCursor(null, 'prev'); // Descending order (newest first)
   586→
   587→        request.onsuccess = (event) => {
   588→          const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   589→          if (cursor) {
   590→            results.push(cursor.value as SimulationMetadata);
   591→            cursor.continue();
   592→          } else {
   593→            resolve(results);
   594→          }
   595→        };
   596→
   597→        request.onerror = () => reject(request.error);
   598→      });
   599→    } catch (error) {
   600→      console.error('[EventDB] Failed to list simulations:', error);
   601→      return [];
   602→    }
   603→  }
   604→
   605→  /**
   606→   * Delete a simulation and all its saves
   607→   *
   608→   * @param simulationId - Base simulation ID (e.g., "42000_historical")
   609→   */
   610→  async deleteSimulation(simulationId: string): Promise<void> {
   611→    await this.init();
   612→    if (!this.db) return;
   613→
   614→    try {
   615→      const transaction = this.db.transaction([SIMULATIONS_STORE, METADATA_STORE, STORE_NAME], 'readwrite');
   616→      const simulationsStore = transaction.objectStore(SIMULATIONS_STORE);
   617→      const metadataStore = transaction.objectStore(METADATA_STORE);
   618→      const eventsStore = transaction.objectStore(STORE_NAME);
   619→
   620→      // Delete all simulation saves
   621→      const simulationsIndex = simulationsStore.index('simulationId');
   622→      const simulationsCursor = simulationsIndex.openCursor(IDBKeyRange.only(simulationId));
   623→
   624→      simulationsCursor.onsuccess = (event) => {
   625→        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   626→        if (cursor) {
   627→          cursor.delete();
   628→          cursor.continue();
   629→        }
   630→      };
   631→
   632→      // Delete metadata
   633→      metadataStore.delete(simulationId);
   634→
   635→      // Delete all events
   636→      const eventsIndex = eventsStore.index('simulationId');
   637→      const eventsCursor = eventsIndex.openCursor(IDBKeyRange.only(simulationId));
   638→
   639→      eventsCursor.onsuccess = (event) => {
   640→        const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   641→        if (cursor) {
   642→          cursor.delete();
   643→          cursor.continue();
   644→        }
   645→      };
   646→
   647→      await new Promise<void>((resolve, reject) => {
   648→        transaction.oncomplete = () => {
   649→          console.log(`[EventDB] Deleted simulation ${simulationId}`);
   650→          resolve();
   651→        };
   652→        transaction.onerror = () => reject(transaction.error);
   653→      });
   654→    } catch (error) {
   655→      console.error('[EventDB] Failed to delete simulation:', error);
   656→      throw error;
   657→    }
   658→  }
   659→
   660→  /**
   661→   * Rotate saves to prevent unbounded storage growth
   662→   *
   663→   * Smart rotation: Keep recent saves dense, older saves sparse
   664→   * - Last 5 saves: Keep all (dense recent history)
   665→   * - 6-20 saves back: Keep every other
   666→   * - 21+ saves back: Keep every 5th
   667→   *
   668→   * @param simulationId - Base simulation ID
   669→   * @param maxSaves - Maximum number of saves to keep (default: 10)
   670→   */
   671→  async rotateSaves(simulationId: string, maxSaves: number = 10): Promise<void> {
   672→    await this.init();
   673→    if (!this.db) return;
   674→
   675→    try {
   676→      const transaction = this.db.transaction([SIMULATIONS_STORE], 'readwrite');
   677→      const store = transaction.objectStore(SIMULATIONS_STORE);
   678→      const index = store.index('simulationId');
   679→
   680→      // Get all saves for this simulation, sorted by lastUpdated descending
   681→      const saves = await new Promise<StoredSimulation[]>((resolve, reject) => {
   682→        const results: StoredSimulation[] = [];
   683→        const request = index.openCursor(IDBKeyRange.only(simulationId), 'prev');
   684→
   685→        request.onsuccess = (event) => {
   686→          const cursor = (event.target as IDBRequest<IDBCursorWithValue>).result;
   687→          if (cursor) {
   688→            results.push(cursor.value as StoredSimulation);
   689→            cursor.continue();
   690→          } else {
   691→            resolve(results);
   692→          }
   693→        };
   694→
   695→        request.onerror = () => reject(request.error);
   696→      });
   697→
   698→      if (saves.length <= maxSaves) {
   699→        return; // No rotation needed
   700→      }
   701→
   702→      // Smart rotation logic
   703→      const toKeep = new Set<string>();
   704→
   705→      // Always keep most recent save
   706→      if (saves.length > 0) {
   707→        toKeep.add(saves[0].id);
   708→      }
   709→
   710→      // Keep last 5 saves (dense recent history)
   711→      for (let i = 0; i < Math.min(5, saves.length); i++) {
   712→        toKeep.add(saves[i].id);
   713→      }
   714→
   715→      // Keep every other from 6-20
   716→      for (let i = 5; i < Math.min(20, saves.length); i += 2) {
   717→        if (toKeep.size < maxSaves) {
   718→          toKeep.add(saves[i].id);
   719→        }
   720→      }
   721→
   722→      // Keep every 5th from 21+
   723→      for (let i = 20; i < saves.length; i += 5) {
   724→        if (toKeep.size < maxSaves) {
   725→          toKeep.add(saves[i].id);
   726→        }
   727→      }
   728→
   729→      // Delete saves not in toKeep set
   730→      const deleteTransaction = this.db.transaction([SIMULATIONS_STORE], 'readwrite');
   731→      const deleteStore = deleteTransaction.objectStore(SIMULATIONS_STORE);
   732→
   733→      const toDelete = saves.filter(s => !toKeep.has(s.id));
   734→      for (const save of toDelete) {
   735→        deleteStore.delete(save.id);
   736→      }
   737→
   738→      await new Promise<void>((resolve, reject) => {
   739→        deleteTransaction.oncomplete = () => {
   740→          console.log(`[EventDB] Rotated ${toDelete.length} old saves for ${simulationId}`);
   741→          resolve();
   742→        };
   743→        deleteTransaction.onerror = () => reject(deleteTransaction.error);
   744→      });
   745→    } catch (error) {
   746→      console.error('[EventDB] Failed to rotate saves:', error);
   747→      // Don't throw - rotation failure shouldn't block saves
   748→    }
   749→  }
   750→
   751→  /**
   752→   * Clear all simulation states and metadata
   753→   * (Events are preserved)
   754→   */
   755→  async clearAllSimulations(): Promise<void> {
   756→    await this.init();
   757→    if (!this.db) return;
   758→
   759→    const transaction = this.db.transaction([SIMULATIONS_STORE, METADATA_STORE], 'readwrite');
   760→    const simulationsStore = transaction.objectStore(SIMULATIONS_STORE);
   761→    const metadataStore = transaction.objectStore(METADATA_STORE);
   762→
   763→    return new Promise((resolve, reject) => {
   764→      let completed = 0;
   765→      const checkComplete = () => {
   766→        completed++;
   767→        if (completed === 2) resolve();
   768→      };
   769→
   770→      simulationsStore.clear().onsuccess = checkComplete;
   771→      metadataStore.clear().onsuccess = checkComplete;
   772→
   773→      transaction.onerror = () => reject(transaction.error);
   774→    });
   775→  }
   776→
   777→  /**
   778→   * Estimate storage size of a GameState object
   779→   * @param state - GameState to measure
   780→   * @returns Estimated size in bytes
   781→   */
   782→  estimateStorageSize(state: any): number {
   783→    return JSON.stringify(state).length;
   784→  }
   785→
   786→  /**
   787→   * Get storage quota information
   788→   * @returns Object with usage, quota, and percentage used
   789→   */
   790→  async getStorageQuota(): Promise<{
   791→    usage: number;
   792→    quota: number;
   793→    percentUsed: number;
   794→    available: number;
   795→  } | null> {
   796→    if (typeof navigator === 'undefined' || !navigator.storage || !navigator.storage.estimate) {
   797→      console.warn('[EventDB] Storage quota API not available');
   798→      return null;
   799→    }
   800→
   801→    try {
   802→      const estimate = await navigator.storage.estimate();
   803→      const usage = estimate.usage || 0;
   804→      const quota = estimate.quota || 0;
   805→      const percentUsed = quota > 0 ? (usage / quota) * 100 : 0;
   806→      const available = quota - usage;
   807→
   808→      return {
   809→        usage,
   810→        quota,
   811→        percentUsed,
   812→        available
   813→      };
   814→    } catch (error) {
   815→      console.error('[EventDB] Failed to estimate storage quota:', error);
   816→      return null;
   817→    }
   818→  }
   819→
   820→  /**
   821→   * Check if there's enough space to save a state of given size
   822→   * @param estimatedSize - Estimated size of state in bytes
   823→   * @param warningThreshold - Percentage at which to warn (default: 80%)
   824→   * @returns Object with canSave flag and optional warning message
   825→   */
   826→  async checkStorageSpace(estimatedSize: number, warningThreshold: number = 80): Promise<{
   827→    canSave: boolean;
   828→    warning?: string;
   829→    percentUsed?: number;
   830→  }> {
   831→    const quota = await this.getStorageQuota();
   832→
   833→    if (!quota) {
   834→      // Can't check quota, assume it's OK
   835→      return { canSave: true };
   836→    }
   837→
   838→    const wouldUse = quota.usage + estimatedSize;
   839→    const wouldUsePercent = (wouldUse / quota.quota) * 100;
   840→
   841→    if (wouldUse > quota.quota) {
   842→      return {
   843→        canSave: false,
   844→        warning: `Storage quota exceeded. Need ${(estimatedSize / 1024 / 1024).toFixed(2)} MB, only ${(quota.available / 1024 / 1024).toFixed(2)} MB available.`,
   845→        percentUsed: wouldUsePercent
   846→      };
   847→    }
   848→
   849→    if (wouldUsePercent >= warningThreshold) {
   850→      return {
   851→        canSave: true,
   852→        warning: `Storage ${wouldUsePercent.toFixed(1)}% full. Consider deleting old simulations.`,
   853→        percentUsed: wouldUsePercent
   854→      };
   855→    }
   856→
   857→    return { canSave: true, percentUsed: wouldUsePercent };
   858→  }
   859→}
   860→
   861→// Singleton instance
   862→export const eventDatabase = new EventDatabase();
   863→
   864→// Export types and utility functions
   865→export type { StoredEvent, StoredSimulation, SimulationMetadata };
   866→export { SIMULATION_STATE_VERSION, isVersionCompatible, parseVersion };
   867→

