            className="px-8 py-3 bg-cyan-400/10 border border-cyan-400/60 text-cyan-400 rounded-sm hover:bg-cyan-400/20 hover:shadow-[0_0_20px_rgba(0,240,255,0.3)] transition-all"
          >
            + START FIRST SIMULATION
          </button>
        </div>
