                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-white/60">QoL:</span>
                  <span>{(sim.qualityOfLife * 100).toFixed(1)}%</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-white/60">AI Cap:</span>
                  <span>{sim.aiCapability.toFixed(2)}</span>
