                  >
                    CONTINUE
                  </button>
                ) : (
                  <button
                    onClick={() => handleDownloadSimulation(sim.id)}
                    className="flex-1 px-4 py-2 bg-white/5 border border-white/20 text-white/80 rounded-sm text-sm hover:border-white/40 hover:bg-white/10 transition-all"
                  >
                    DOWNLOAD
                  </button>
