/**
 * Tier 1 Threshold Configurations - Phase 1B
 *
 * Defines research-backed uncertainty distributions for critical simulation thresholds.
 * Uses Phase 1A distribution sampling library for parameter variation.
 *
 * Research Foundation:
 * - Social Critical Mass: Centola et al. (2018, Science) - 25% committed minority
 * - Trust Recovery: Meta-analysis of trust repair interventions
 * - Climate Sensitivity: IPCC AR6 WG1 (2021) - ECS 3.0°C [2.0-5.0°C likely range]
 * - Government Legitimacy: Historical state collapse analysis
 * - Automation Job Loss: Acemoglu & Restrepo (2022) - labor market disruption
 */

import {
  sampleNormal,
  sampleBeta,
  sampleLogNormal,
  sampleTriangular
} from './distributions';

/**
 * Tier 1 Threshold Distribution Definitions
 *
 * These configurations define uncertainty distributions for critical thresholds.
 * Each threshold samples from a research-backed distribution during initialization.
 */

/**
 * 1. SOCIAL CRITICAL MASS
 *
 * Research: Centola et al. (2018, Science) "Experimental evidence for tipping points in social convention"
 * Finding: Committed minorities of ~25% can flip majority opinion
 * Uncertainty: ±2% based on experimental variance
 * Distribution: Normal(μ=0.25, σ=0.02)
 */
export const SOCIAL_CRITICAL_MASS_PARAMS = {
  mean: 0.25,
  stdDev: 0.02,
  bounds: [0.20, 0.30] as [number, number], // Clip to reasonable range
  citation: 'Centola et al. (2018, Science) - tipping points in social convention'
};

/**
 * 2. TRUST RECOVERY RATE (monthly)
 *
 * Research: Meta-analysis of trust repair studies (Gillespie & Dietz 2009, Lewicki & Brinsfield 2017)
 * Finding: Trust recovery is asymmetric - slower than loss
 * Typical recovery: 1-3% per month with intervention (mode ~1.5%)
 * Distribution: Beta(α=2, β=5) rescaled to [0.005, 0.03] (0.5-3% monthly recovery)
 *
 * Beta(2,5) shape: Right-skewed, most weight at lower values (slow recovery typical)
 */
export const TRUST_RECOVERY_RATE_PARAMS = {
  alpha: 2.0,
  beta: 5.0,
  bounds: [0.005, 0.03] as [number, number], // 0.5-3% monthly recovery
  citation: 'Gillespie & Dietz (2009), Lewicki & Brinsfield (2017) - trust repair meta-analysis'
};

/**
 * 3. CLIMATE SENSITIVITY (Equilibrium Climate Sensitivity, ECS)
 *
 * Research: IPCC AR6 WG1 (2021) Chapter 7 - Earth's Energy Budget
 * Finding: Best estimate 3.0°C, likely range 2.5-4.0°C, very likely 2.0-5.0°C
 * Distribution: Log-Normal(μ=3.0, σ=0.75) captures right-skewed uncertainty
 *
 * Log-normal justification: Physical constraints prevent negative ECS, small chance of high ECS
 * Note: This is ECS in °C, needs conversion to simulation degradation rate
 */
export const CLIMATE_SENSITIVITY_PARAMS = {
  mu: 3.0,
  sigma: 0.75,
  bounds: [2.0, 5.0] as [number, number], // IPCC very likely range
  citation: 'IPCC AR6 WG1 (2021) Ch 7 - Equilibrium Climate Sensitivity'
};

/**
 * 4. GOVERNMENT LEGITIMACY CRISIS THRESHOLD
 *
 * Research: Historical state collapse analysis (Weimar, USSR, various failed states)
 * Finding: Collapse typically occurs 25-40% legitimacy, mode ~30%
 * Distribution: Triangular(min=0.25, mode=0.30, max=0.40)
 *
 * Triangular justification: Expert elicitation with clear mode, bounded by historical cases
 * Below 25%: Nearly always collapse
 * 30%: Most common collapse point
 * Above 40%: Rare to collapse (other factors usually intervene)
 */
export const GOVERNMENT_LEGITIMACY_CRISIS_PARAMS = {
  min: 0.25,
  mode: 0.30,
  max: 0.40,
  citation: 'Historical state collapse analysis (Weimar, USSR, failed states)'
};

/**
 * 5. AUTOMATION JOB LOSS THRESHOLD
 *
 * Research: Acemoglu & Restrepo (2022) "Tasks, Automation, and the Rise in US Wage Inequality"
 * Finding: Automation displaces ~35% of routine tasks, ±5% based on policy/adaptation
 * Distribution: Normal(μ=0.35, σ=0.05)
 *
 * Note: This is the unemployment level at which automation-driven crises trigger
 * Societies with strong safety nets tolerate higher unemployment (40%)
 * Societies with weak safety nets crisis at lower levels (30%)
 */
export const AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS = {
  mean: 0.35,
  stdDev: 0.05,
  bounds: [0.25, 0.45] as [number, number], // Clip to plausible range
  citation: 'Acemoglu & Restrepo (2022) - automation and labor market disruption'
};

/**
 * Sample all Tier 1 thresholds for a simulation run
 *
 * @param rng - Random number generator function (for deterministic seeding)
 * @returns Sampled threshold values
 */
export interface Tier1Thresholds {
  socialCriticalMass: number;
  trustRecoveryRate: number;
  climateSensitivity: number;
  governmentLegitimacyCrisisThreshold: number;
  automationJobLossThreshold: number;
}

export function sampleTier1Thresholds(rng: () => number): Tier1Thresholds {
  // Sample raw values from distributions
  const socialCriticalMass = sampleNormal(
    SOCIAL_CRITICAL_MASS_PARAMS.mean,
    SOCIAL_CRITICAL_MASS_PARAMS.stdDev,
    rng
  );

  const trustRecoveryRateRaw = sampleBeta(
    TRUST_RECOVERY_RATE_PARAMS.alpha,
    TRUST_RECOVERY_RATE_PARAMS.beta,
    rng
  );

  const climateSensitivity = sampleLogNormal(
    CLIMATE_SENSITIVITY_PARAMS.mu,
    CLIMATE_SENSITIVITY_PARAMS.sigma,
    rng
  );

  const governmentLegitimacyCrisisThreshold = sampleTriangular(
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.min,
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.mode,
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.max,
    rng
  );

  const automationJobLossThreshold = sampleNormal(
    AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.mean,
    AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.stdDev,
    rng
  );

  // Apply bounds by clamping to valid ranges
  return {
    socialCriticalMass: Math.max(
      SOCIAL_CRITICAL_MASS_PARAMS.bounds[0],
      Math.min(SOCIAL_CRITICAL_MASS_PARAMS.bounds[1], socialCriticalMass)
    ),
    trustRecoveryRate: TRUST_RECOVERY_RATE_PARAMS.bounds[0] +
      (trustRecoveryRateRaw * (TRUST_RECOVERY_RATE_PARAMS.bounds[1] - TRUST_RECOVERY_RATE_PARAMS.bounds[0])),
    climateSensitivity: Math.max(
      CLIMATE_SENSITIVITY_PARAMS.bounds[0],
      Math.min(CLIMATE_SENSITIVITY_PARAMS.bounds[1], climateSensitivity)
    ),
    governmentLegitimacyCrisisThreshold: governmentLegitimacyCrisisThreshold, // Already bounded by triangular
    automationJobLossThreshold: Math.max(
      AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.bounds[0],
      Math.min(AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.bounds[1], automationJobLossThreshold)
    )
  };
}

/**
 * Convert climate sensitivity (°C per doubling CO2) to simulation degradation rate
 *
 * IPCC AR6: Current trajectory is ~SSP5-8.5 (high emissions)
 * - Emissions double CO2 every ~35-50 years at current pace
 * - ECS determines final warming, but rate depends on emissions path
 *
 * Simplified conversion for simulation:
 * - Base rate calibrated to IPCC SSP5-8.5 trajectory (0.00015 for ECS=3.0°C)
 * - Scale linearly with ECS (higher sensitivity = faster degradation)
 *
 * @param climateSensitivity - Sampled ECS value (°C)
 * @returns Monthly climate degradation rate
 */
export function convertClimateSensitivityToRate(climateSensitivity: number): number {
  const BASELINE_ECS = 3.0; // IPCC best estimate
  const BASELINE_RATE = 0.00015; // Calibrated to IPCC SSP5-8.5

  // Scale rate linearly with ECS
  // ECS=2.0°C → 67% of baseline rate
  // ECS=3.0°C → 100% of baseline rate
  // ECS=5.0°C → 167% of baseline rate
  return BASELINE_RATE * (climateSensitivity / BASELINE_ECS);
}

/**
 * Tier 2 Threshold Configurations - Phase 2
 *
 * Defines historical range-based uncertainty distributions for semi-known thresholds.
 * Uses Phase 1A distribution sampling library (Uniform/Triangular only for Tier 2).
 *
 * Research Foundation: research/threshold_tier2_historical_ranges_20251026.md
 * - Government Legitimacy: Weimar, USSR, Arab Spring cases (1930-2011)
 * - Surveillance Dystopia: East Germany, China, North Korea cases (1950-present)
 * - Automation Displacement: Industrial Revolution, Great Depression, modern cases (1770-2023)
 * - AI Recursive Improvement: Moore's Law, AlphaGo, software bootstrapping analogs
 * - Resentment Revolt: French Revolution, Russian Revolution, Occupy, Arab Spring (1789-2019)
 */

import {
  sampleTriangular
} from './distributions';

/**
 * Tier 2 Threshold Distribution Definitions
 *
 * These configurations define uncertainty distributions based on historical ranges.
 * Each threshold samples from Uniform or Triangular distributions during initialization.
 */

/**
 * 1. GOVERNMENT LEGITIMACY CRISIS THRESHOLD
 *
 * Research: Historical state collapse analysis (Weimar, USSR, Arab Spring)
 * Finding: Collapse typically occurs at 25-40% legitimacy, mode ~30%
 * Distribution: Triangular(min=0.25, mode=0.30, max=0.40)
 *
 * Evidence:
 * - USSR 1991: ~0.20-0.25 legitimacy → peaceful dissolution
 * - Weimar 1933: ~0.25-0.30 legitimacy → democratic collapse
 * - Tunisia 2011: ~0.28-0.32 legitimacy → regime overthrow (28 days)
 * - Egypt 2011: ~0.30-0.35 legitimacy → regime change
 * - Syria 2011: ~0.35-0.40 legitimacy → regime survived via repression
 */
export const GOVERNMENT_LEGITIMACY_CRISIS_PARAMS = {
  min: 0.25,
  mode: 0.30,
  max: 0.40,
  citation: 'Historical state collapse analysis (Weimar, USSR, Arab Spring)'
};

/**
 * 2. SURVEILLANCE DYSTOPIA THRESHOLD
 *
 * Research: Authoritarian surveillance states (East Germany, China, North Korea, USSR)
 * Finding: Stable oppression at 65-80% surveillance intensity
 * Distribution: Uniform[0.65, 0.80]
 *
 * Evidence:
 * - East Germany (Stasi): ~0.75-0.85 intensity → 40 years stable repression
 * - China Social Credit: ~0.70-0.80 intensity → stable authoritarian governance
 * - North Korea: ~0.80-0.90 intensity → 75+ years stability
 * - USSR KGB: ~0.60-0.70 intensity → stable until economic collapse
 * - UK (comparison): ~0.40-0.50 intensity → democratic stability
 *
 * Note: No clear mode (varies by technology era: analog Stasi vs digital China)
 */
export const SURVEILLANCE_DYSTOPIA_THRESHOLD_PARAMS = {
  min: 0.65,
  max: 0.80,
  citation: 'Authoritarian surveillance states (East Germany, China, North Korea, USSR)'
};

/**
 * 3. AUTOMATION DISPLACEMENT CRISIS THRESHOLD (Unemployment Rate)
 *
 * Research: Industrial Revolution, Great Depression, modern automation waves
 * Finding: 40-60% unemployment triggers crisis, mode ~50%
 * Distribution: Triangular(min=0.40, mode=0.50, max=0.60)
 *
 * Evidence:
 * - Industrial Revolution UK: 15-20% unemployment → Luddite riots, Chartist movement
 * - Great Depression USA: 24.9% peak unemployment → severe political instability
 * - Post-WWII automation: <6% unemployment (smooth transition, no crisis)
 * - China youth unemployment (2023): 20%+ → "lying flat" movement
 * - Spain youth unemployment (2013): 56.5% → 15M movement protests
 *
 * Expert estimates:
 * - Acemoglu & Restrepo (2022): 40-60% routine task automation = crisis threshold
 * - McKinsey (2017): 25%+ unemployment without retraining = crisis
 */
export const AUTOMATION_DISPLACEMENT_CRISIS_PARAMS = {
  min: 0.40,
  mode: 0.50,
  max: 0.60,
  citation: 'Industrial Revolution, Great Depression, modern automation (Acemoglu & Restrepo 2022)'
};

/**
 * 4. AI RECURSIVE IMPROVEMENT THRESHOLD (Monthly Capability Multiplier)
 *
 * Research: Technological improvement curve analogs (Moore's Law, AlphaGo, software bootstrapping)
 * Finding: 1.2-1.5× monthly multiplier based on analogs
 * Distribution: Uniform[1.2, 1.5]
 *
 * Evidence (ANALOGS - no direct precedent):
 * - Moore's Law: ~1.5× annual multiplier sustained for 40 years (transistor density)
 * - AlphaGo Zero: ~1.5× daily improvement (short-term, hit ceiling quickly)
 * - Software bootstrapping: ~1.2-1.3× per generation (C compiler, 1970s-1980s)
 * - Scientific research: NEGATIVE productivity growth (-1% to -5% annually, Bloom et al. 2020)
 *
 * Note: HIGHLY SPECULATIVE - no direct historical precedent for AI recursive improvement.
 * Range captures uncertainty about unprecedented phenomenon.
 */
export const AI_RECURSIVE_IMPROVEMENT_THRESHOLD_PARAMS = {
  min: 1.2,
  max: 1.5,
  citation: 'Technological improvement curve analogs (Moore\'s Law, AlphaGo, software bootstrapping)'
};

/**
 * 5. RESENTMENT REVOLT TRIGGER THRESHOLD (Composite Resentment Metric)
 *
 * Research: Historical revolutions and uprisings (1789-2019)
 * Finding: 60-80% resentment triggers revolt, mode ~70%
 * Distribution: Triangular(min=0.60, mode=0.70, max=0.80)
 *
 * Evidence:
 * - French Revolution (1789): ~0.75-0.85 resentment → violent revolution
 * - Russian Revolution (1917): ~0.70-0.80 resentment → Bolshevik revolution
 * - Occupy Wall Street (2011): ~0.55-0.65 resentment → protests (no revolution, democratic safety valves)
 * - Arab Spring (2010-2012): ~0.60-0.70 resentment → mixed outcomes
 * - Hong Kong (2019-2020): ~0.60-0.70 resentment → protests suppressed
 * - Yellow Vests France (2018-2019): ~0.55-0.65 resentment → sustained protests, concessions
 *
 * Composite metric combines:
 * - Economic inequality (Gini coefficient)
 * - Political exclusion (representation gap)
 * - Perceived unfairness (AI/elite privilege)
 * - Control erosion (government legitimacy loss)
 */
export const RESENTMENT_REVOLT_TRIGGER_PARAMS = {
  min: 0.60,
  mode: 0.70,
  max: 0.80,
  citation: 'Historical revolutions (French, Russian, Arab Spring, Occupy) - Gurr (1970), Acemoglu & Robinson (2006)'
};

/**
 * Sample all Tier 2 thresholds for a simulation run
 *
 * @param rng - Random number generator function (for deterministic seeding)
 * @returns Sampled threshold values
 */
export interface Tier2Thresholds {
  /** Government legitimacy level triggering collapse/revolution [0.25-0.40] */
  governmentLegitimacyCrisisThreshold: number;

  /** Surveillance intensity triggering stable dystopia [0.65-0.80] */
  surveillanceDystopiaThreshold: number;

  /** Unemployment rate triggering automation crisis [0.40-0.60] */
  automationDisplacementCrisisThreshold: number;

  /** AI capability monthly multiplier enabling recursive improvement [1.2-1.5] */
  aiRecursiveImprovementThreshold: number;

  /** Composite resentment level triggering revolt [0.60-0.80] */
  resentmentRevoltTriggerThreshold: number;
}

export function sampleTier2Thresholds(rng: () => number): Tier2Thresholds {
  // Sample from distributions
  const governmentLegitimacyCrisisThreshold = sampleTriangular(
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.min,
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.mode,
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.max,
    rng
  );

  // Surveillance dystopia: Uniform distribution (no clear mode across analog/digital eras)
  const surveillanceDystopiaThreshold =
    SURVEILLANCE_DYSTOPIA_THRESHOLD_PARAMS.min +
    rng() * (SURVEILLANCE_DYSTOPIA_THRESHOLD_PARAMS.max - SURVEILLANCE_DYSTOPIA_THRESHOLD_PARAMS.min);

  const automationDisplacementCrisisThreshold = sampleTriangular(
    AUTOMATION_DISPLACEMENT_CRISIS_PARAMS.min,
    AUTOMATION_DISPLACEMENT_CRISIS_PARAMS.mode,
    AUTOMATION_DISPLACEMENT_CRISIS_PARAMS.max,
    rng
  );

  // AI recursive improvement: Uniform distribution (no precedent, genuine uncertainty)
  const aiRecursiveImprovementThreshold =
    AI_RECURSIVE_IMPROVEMENT_THRESHOLD_PARAMS.min +
    rng() * (AI_RECURSIVE_IMPROVEMENT_THRESHOLD_PARAMS.max - AI_RECURSIVE_IMPROVEMENT_THRESHOLD_PARAMS.min);

  const resentmentRevoltTriggerThreshold = sampleTriangular(
    RESENTMENT_REVOLT_TRIGGER_PARAMS.min,
    RESENTMENT_REVOLT_TRIGGER_PARAMS.mode,
    RESENTMENT_REVOLT_TRIGGER_PARAMS.max,
    rng
  );

  return {
    governmentLegitimacyCrisisThreshold,
    surveillanceDystopiaThreshold,
    automationDisplacementCrisisThreshold,
    aiRecursiveImprovementThreshold,
    resentmentRevoltTriggerThreshold
  };
}

/**
 * Unified Threshold System - Phase 4: Integration & Scenario Builder
 *
 * Central entry point for threshold uncertainty system combining:
 * - Tier 1: Empirical distributions (Phase 1A/1B)
 * - Tier 2: Historical ranges (Phase 2)
 * - Tier 3: Named scenarios (Phase 3)
 *
 * This module provides:
 * 1. Unified threshold sampling (sampleAllThresholds)
 * 2. Scenario-based configuration
 * 3. Slider-based distribution overrides
 * 4. Export/import for reproducibility
 */

import { sampleTier1Thresholds, type Tier1Thresholds } from './tier1Config';
import { sampleTier2Thresholds, type Tier2Thresholds } from './tier2Config';

/**
 * Combined threshold interface - all tiers unified
 */
export type AllThresholds = Tier1Thresholds & Tier2Thresholds;

/**
 * Named scenario definitions (Tier 3)
 *
 * Each scenario represents a coherent worldview about threshold values:
 * - doom: Pessimistic (low thresholds = easy to trigger crises)
 * - cautious: Conservative (slightly below baseline)
 * - baseline: Central estimates (research mode values)
 * - progressive: Optimistic (slightly above baseline)
 * - utopia: Highly optimistic (high thresholds = resilient systems)
 */
export type ScenarioName = 'doom' | 'cautious' | 'baseline' | 'progressive' | 'utopia';

/**
 * Slider settings for threshold distribution overrides
 *
 * Sliders map threshold names to quantile positions [0.0, 1.0]:
 * - 0.0 = pessimistic extreme (lowest value in distribution)
 * - 0.5 = median/mode (central estimate)
 * - 1.0 = optimistic extreme (highest value in distribution)
 *
 * Example: { climateSensitivity: 0.9 } → sample at 90th percentile (high sensitivity)
 */
export type SliderSettings = Partial<Record<keyof AllThresholds, number>>;

/**
 * Threshold sampling options
 */
export interface ThresholdSamplingOptions {
  /** Named scenario selection (overrides slider defaults) */
  scenario?: ScenarioName;

  /** Custom slider overrides (take precedence over scenario) */
  sliders?: SliderSettings;

  /** Use nested Monte Carlo (epistemic/aleatory separation) - Phase 1C */
  nested?: boolean;
}

/**
 * Get slider settings for a named scenario
 *
 * Scenarios define coherent worldviews by setting multiple sliders together.
 * These represent different uncertainty perspectives, not "game difficulty."
 *
 * Research foundation:
 * - DOOM: Taleb (2007) "The Black Swan" - fat-tailed risk, fragile systems
 * - CAUTIOUS: Precautionary principle, IPCC likely ranges (16th-84th percentile)
 * - BASELINE: Research mode values (central estimates)
 * - PROGRESSIVE: Technological optimism, Pinker (2018) "Enlightenment Now"
 * - UTOPIA: Bostrom (2014) optimistic scenarios, robust institutions
 */
function getScenarioSliders(scenario: ScenarioName): SliderSettings {
  switch (scenario) {
    case 'doom':
      // Pessimistic: Systems are fragile, thresholds are low
      return {
        // Social systems collapse easily
        socialCriticalMass: 0.2,           // Low critical mass (easier to flip)
        trustRecoveryRate: 0.1,            // Slow trust recovery
        governmentLegitimacyCrisisThreshold: 0.2, // Collapses at high legitimacy

        // Climate/environment is severe
        climateSensitivity: 0.9,           // High ECS (severe warming)

        // Automation/AI is disruptive
        automationJobLossThreshold: 0.2,   // Crisis at low unemployment
        automationDisplacementCrisisThreshold: 0.2,
        aiRecursiveImprovementThreshold: 0.8, // Fast AI improvement

        // Control/surveillance is easy
        surveillanceDystopiaThreshold: 0.2, // Low threshold for stable dystopia

        // Resentment triggers easily
        resentmentRevoltTriggerThreshold: 0.2 // Low resentment needed for revolt
      };

    case 'cautious':
      // Conservative: Below baseline, precautionary principle
      return {
        socialCriticalMass: 0.35,
        trustRecoveryRate: 0.35,
        climateSensitivity: 0.65,
        governmentLegitimacyCrisisThreshold: 0.35,
        automationJobLossThreshold: 0.35,
        automationDisplacementCrisisThreshold: 0.35,
        aiRecursiveImprovementThreshold: 0.65,
        surveillanceDystopiaThreshold: 0.35,
        resentmentRevoltTriggerThreshold: 0.35
      };

    case 'baseline':
      // Central estimates: Research mode values (median/mode)
      return {
        socialCriticalMass: 0.5,
        trustRecoveryRate: 0.5,
        climateSensitivity: 0.5,
        governmentLegitimacyCrisisThreshold: 0.5,
        automationJobLossThreshold: 0.5,
        automationDisplacementCrisisThreshold: 0.5,
        aiRecursiveImprovementThreshold: 0.5,
        surveillanceDystopiaThreshold: 0.5,
        resentmentRevoltTriggerThreshold: 0.5
      };

    case 'progressive':
      // Optimistic: Above baseline, technological optimism
      return {
        socialCriticalMass: 0.65,
        trustRecoveryRate: 0.65,
        climateSensitivity: 0.35,
        governmentLegitimacyCrisisThreshold: 0.65,
        automationJobLossThreshold: 0.65,
        automationDisplacementCrisisThreshold: 0.65,
        aiRecursiveImprovementThreshold: 0.35,
        surveillanceDystopiaThreshold: 0.65,
        resentmentRevoltTriggerThreshold: 0.65
      };

    case 'utopia':
      // Highly optimistic: Systems are robust, thresholds are high
      return {
        socialCriticalMass: 0.8,           // High critical mass (harder to flip)
        trustRecoveryRate: 0.9,            // Fast trust recovery
        climateSensitivity: 0.1,           // Low ECS (mild warming)
        governmentLegitimacyCrisisThreshold: 0.8, // Only collapses at very low legitimacy
        automationJobLossThreshold: 0.8,   // Crisis only at high unemployment
        automationDisplacementCrisisThreshold: 0.8,
        aiRecursiveImprovementThreshold: 0.2, // Slow AI improvement
        surveillanceDystopiaThreshold: 0.8, // High threshold for dystopia
        resentmentRevoltTriggerThreshold: 0.8 // High resentment needed for revolt
      };
  }
}

/**
 * Apply slider value to a distribution by sampling at quantile position
 *
 * For most distributions, slider=0.5 samples at median/mode.
 * For bounded distributions (Uniform, Triangular), linear interpolation.
 *
 * @param min - Minimum value of distribution
 * @param max - Maximum value of distribution
 * @param slider - Quantile position [0.0, 1.0]
 * @param mode - Optional mode for triangular distributions
 * @returns Sampled value at quantile position
 */
function applySlider(min: number, max: number, slider: number, mode?: number): number {
  // Clamp slider to [0, 1]
  const s = Math.max(0, Math.min(1, slider));

  // For triangular distributions with mode
  if (mode !== undefined) {
    // Simplified: Use inverse CDF of triangular distribution
    // This is approximate - full implementation would use proper inverse CDF
    if (s <= 0.5) {
      // Left half: interpolate from min to mode
      return min + (mode - min) * (s * 2);
    } else {
      // Right half: interpolate from mode to max
      return mode + (max - mode) * ((s - 0.5) * 2);
    }
  }

  // For uniform distributions: linear interpolation
  return min + (max - min) * s;
}

/**
 * Sample all thresholds with optional scenario/slider overrides
 *
 * Priority order:
 * 1. Custom sliders (highest priority)
 * 2. Scenario sliders
 * 3. Random sampling from distributions (default)
 *
 * @param rng - Random number generator function (for deterministic seeding)
 * @param options - Sampling options (scenario, sliders, nested mode)
 * @returns Sampled threshold values
 */
export function sampleAllThresholds(
  rng: () => number,
  options: ThresholdSamplingOptions = {}
): AllThresholds {
  const { scenario, sliders = {}, nested = false } = options;

  // Get scenario sliders if specified
  const scenarioSliders = scenario ? getScenarioSliders(scenario) : {};

  // Merge sliders: custom sliders override scenario sliders
  const finalSliders: SliderSettings = { ...scenarioSliders, ...sliders };

  // Sample Tier 1 thresholds with slider overrides
  const tier1Raw = sampleTier1Thresholds(rng);
  const tier1: Tier1Thresholds = {
    socialCriticalMass: finalSliders.socialCriticalMass !== undefined
      ? applySlider(0.20, 0.30, finalSliders.socialCriticalMass)
      : tier1Raw.socialCriticalMass,

    trustRecoveryRate: finalSliders.trustRecoveryRate !== undefined
      ? applySlider(0.005, 0.03, finalSliders.trustRecoveryRate)
      : tier1Raw.trustRecoveryRate,

    climateSensitivity: finalSliders.climateSensitivity !== undefined
      ? applySlider(2.0, 5.0, finalSliders.climateSensitivity)
      : tier1Raw.climateSensitivity,

    governmentLegitimacyCrisisThreshold: finalSliders.governmentLegitimacyCrisisThreshold !== undefined
      ? applySlider(0.25, 0.40, finalSliders.governmentLegitimacyCrisisThreshold, 0.30)
      : tier1Raw.governmentLegitimacyCrisisThreshold,

    automationJobLossThreshold: finalSliders.automationJobLossThreshold !== undefined
      ? applySlider(0.25, 0.45, finalSliders.automationJobLossThreshold)
      : tier1Raw.automationJobLossThreshold
  };

  // Sample Tier 2 thresholds with slider overrides
  const tier2Raw = sampleTier2Thresholds(rng);
  const tier2: Tier2Thresholds = {
    governmentLegitimacyCrisisThreshold: finalSliders.governmentLegitimacyCrisisThreshold !== undefined
      ? applySlider(0.25, 0.40, finalSliders.governmentLegitimacyCrisisThreshold, 0.30)
      : tier2Raw.governmentLegitimacyCrisisThreshold,

    surveillanceDystopiaThreshold: finalSliders.surveillanceDystopiaThreshold !== undefined
      ? applySlider(0.65, 0.80, finalSliders.surveillanceDystopiaThreshold)
      : tier2Raw.surveillanceDystopiaThreshold,

    automationDisplacementCrisisThreshold: finalSliders.automationDisplacementCrisisThreshold !== undefined
      ? applySlider(0.40, 0.60, finalSliders.automationDisplacementCrisisThreshold, 0.50)
      : tier2Raw.automationDisplacementCrisisThreshold,

    aiRecursiveImprovementThreshold: finalSliders.aiRecursiveImprovementThreshold !== undefined
      ? applySlider(1.2, 1.5, finalSliders.aiRecursiveImprovementThreshold)
      : tier2Raw.aiRecursiveImprovementThreshold,

    resentmentRevoltTriggerThreshold: finalSliders.resentmentRevoltTriggerThreshold !== undefined
      ? applySlider(0.60, 0.80, finalSliders.resentmentRevoltTriggerThreshold, 0.70)
      : tier2Raw.resentmentRevoltTriggerThreshold
  };

  // Combine all tiers
  // Note: governmentLegitimacyCrisisThreshold appears in both Tier 1 and Tier 2
  // Use Tier 2 version (more recent, historical range-based)
  return {
    ...tier1,
    ...tier2
  };
}

